window.UMMAHTI_LIBRARY={"source":"Ummahti Quran app: feature/duas and data/reflectionlibrary (published entries only)","collections":["الشدّة والكرب","الهمّ والحزن","المرض والشفاء","المغفرة والتوبة","الحفظ والاستعاذة","الأهل","الرزق والدَّين","السفر","النوم والاستيقاظ","أذكار اليوم","الهداية والعلم"],"duas":[{"id":"dua_distress_yunus","k":0,"t":"حين تشعر أنّك محاصَر ولا مخرج","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[21,87,87],"ar":null,"tr":"La ilaha illa anta, subhanaka inni kuntu mina z-zalimin","src":null},{"id":"dua_burden_baqarah","k":0,"t":"حين يُطلب منك أكثر ممّا تُطيق","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[2,286,286],"ar":null,"tr":"Rabbana la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna","src":null},{"id":"dua_sufficiency_of_allah","k":0,"t":"حين تخاف أو تشعر أنّك أضعف","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[3,173,173],"ar":null,"tr":"Hasbunallahu wa ni'ma l-wakil","src":null},{"id":"dua_affliction_ayyub","k":2,"t":"حين يطول البلاء","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[21,83,83],"ar":null,"tr":"Anni massaniya d-durru wa anta arhamu r-rahimin","src":null},{"id":"dua_ease_musa","k":10,"t":"قبل أمر صعب عليك مواجهته","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[20,25,28],"ar":null,"tr":"Rabbi shrah li sadri, wa yassir li amri, wahlul 'uqdatan min lisani, yafqahu qawli","src":null},{"id":"dua_turning_back","k":3,"t":"حين تظلم نفسك وتريد العودة","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[7,23,23],"ar":null,"tr":"Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna mina l-khasirin","src":null},{"id":"dua_firm_heart","k":10,"t":"حين يزعزع الشكّ قلبك","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[3,8,8],"ar":null,"tr":"Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana min ladunka rahmah, innaka anta l-Wahhab","src":null},{"id":"dua_increase_knowledge","k":10,"t":"قبل الدراسة، وكلّما طلبت العلم","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[20,114,114],"ar":null,"tr":"Rabbi zidni 'ilma","src":null},{"id":"dua_righteous_family","k":5,"t":"لزوج صالح وذرّية طيّبة","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[25,74,74],"ar":null,"tr":"Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil-muttaqina imama","src":null},{"id":"dua_mercy_for_parents","k":5,"t":"لوالديك، أحياءً كانوا أو أمواتًا","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[17,24,24],"ar":null,"tr":"Rabbi rhamhuma kama rabbayani saghira","src":null},{"id":"dua_good_in_both_worlds","k":9,"t":"لخير الدنيا والآخرة","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[2,201,201],"ar":null,"tr":"Rabbana atina fi d-dunya hasanatan wa fi l-akhirati hasanatan wa qina 'adhaba n-nar","src":null},{"id":"dua_ayat_al_kursi_night","k":8,"t":"قبل أن تنام","m":null,"o":"قراءة آية الكرسي قبل النوم مرويّة في صحيح البخاري 3275.","q":[2,255,255],"ar":null,"tr":null,"src":null},{"id":"dua_worry_and_debt","k":1,"t":"حين يثقلك الهمّ أو العجز أو الدَّين","m":"اللهمّ إنّي أستجير بك من الهمّ والحزن، ومن العجز والكسل، ومن البخل والجبن، ومن ثقل الدَّين وغلبة الرجال.","o":"رُوي في صحيح البخاري 6363 أنّه دعاء كان النبيّ ﷺ يقوله. ولم يُنقل معه عدد من التكرار.","q":null,"ar":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","tr":"Allahumma inni a'udhu bika mina l-hammi wa l-hazan, wa l-'ajzi wa l-kasal, wa l-bukhli wa l-jubn, wa dala'i d-dayni wa ghalabati r-rijal","src":{"c":"Sahih al-Bukhari","r":"6363","u":"https://sunnah.com/bukhari:6363","g":"Sahih"}},{"id":"dua_sayyid_al_istighfar","k":3,"t":"حين تعود إلى الله وتطلب المغفرة","m":"اللهمّ أنت ربّي، لا إله إلّا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت، أعوذ بك من شرّ ما صنعت، أُقرّ لك بنعمتك عليّ، وأُقرّ بذنبي، فاغفر لي، فإنّه لا يغفر الذنوب إلّا أنت.","o":"رُوي في صحيح البخاري 6306، حيث علّمه النبيّ ﷺ بوصفه أفضل ما يُستغفَر به الله.","q":null,"ar":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","tr":"Allahumma anta Rabbi, la ilaha illa anta, khalaqtani wa ana 'abduk, wa ana 'ala 'ahdika wa wa'dika ma stata't. A'udhu bika min sharri ma sana't. Abu'u laka bi ni'matika 'alayya, wa abu'u laka bi dhanbi faghfir li, fa innahu la yaghfiru dh-dhunuba illa ant","src":{"c":"Sahih al-Bukhari","r":"6306","u":"https://sunnah.com/bukhari:6306","g":"Sahih"}},{"id":"dua_on_calamity","k":1,"t":"عند وقوع مصيبة أو فقد","m":"اللهمّ أْجُرني في مصيبتي، واخلُف لي خيرًا منها.","o":"رُوي في صحيح مسلم 918a أنّه يُقال عند المصيبة، مع الكلمات التي علّمها القرآن في 2:156.","q":null,"ar":"اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا","tr":"Allahumma'jurni fi musibati, wakhluf li khayran minha","src":{"c":"Sahih Muslim","r":"918a","u":"https://sunnah.com/muslim:918a","g":"Sahih"}},{"id":"dua_distress_supplication","k":0,"t":"حين يضيق بك أمرٌ ويشتدّ","m":"لا إله إلّا الله العظيم الحليم. لا إله إلّا الله ربّ العرش العظيم. لا إله إلّا الله ربّ السماوات وربّ الأرض وربّ العرش الكريم.","o":"وردَ أنّه كان يُقال عند الكرب.","q":null,"ar":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","tr":"La ilaha illa Allahu l-'Azimu l-Halim, la ilaha illa Allahu Rabbu l-'arshi l-'azim, la ilaha illa Allahu Rabbu s-samawati wa Rabbu l-ardi wa Rabbu l-'arshi l-karim","src":{"c":"Sahih Muslim","r":"2730a","u":"https://sunnah.com/muslim:2730a","g":"Sahih"}},{"id":"dua_hope_in_mercy","k":0,"t":"حين لا تقدر على أمرك وحدك","m":"اللهمّ رحمتَك أرجو، فلا تكلني إلى نفسي طرفةَ عين، وأصلح لي شأني كلّه. لا إله إلّا أنت.","o":"وردَ أنّه كان يُقال عند الكرب.","q":null,"ar":"اللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ","tr":"Allahumma rahmataka arju fa la takilni ila nafsi tarfata 'ayn, wa aslih li sha'ni kullah, la ilaha illa ant","src":{"c":"Sunan Abi Dawud","r":"5090","u":"https://sunnah.com/abudawud:5090","g":"Hasan in chain (per al-Albani)"}},{"id":"dua_allah_is_my_lord","k":0,"t":"كلماتٌ قليلة تتعلّق بها","m":"الله الله ربّي، لا أُشرك به شيئًا.","o":"وردَ أنّه كان يُقال عند الكرب.","q":null,"ar":"اللَّهُ اللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","tr":"Allahu Allahu Rabbi la ushriku bihi shay'a","src":{"c":"Sunan Abi Dawud","r":"1525","u":"https://sunnah.com/abudawud:1525","g":"Sahih (per al-Albani)"}},{"id":"dua_shield_against_them","k":0,"t":"حين تخاف من الناس","m":"اللهمّ إنّا نجعلك في نحورهم، ونعوذ بك من شرورهم.","o":"وردَ أنّه ﷺ كان يقوله إذا خاف قومًا.","q":null,"ar":"اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ","tr":"Allahumma inna naj'aluka fi nuhurihim, wa na'udhu bika min shururihim","src":{"c":"Sunan Abi Dawud","r":"1537","u":"https://sunnah.com/abudawud:1537","g":"Sahih (per al-Albani)"}},{"id":"dua_decree_of_allah","k":0,"t":"حين يقع الأمر ولا يُرَدّ","m":"قدَّر الله وما شاء فعل.","o":"وردَ أنّه ما يُقال إذا وقع أمرٌ لم يُرَد، بدلًا من قول «لو أنّي».","q":null,"ar":"قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ","tr":"Qaddara Allahu wa ma sha'a fa'al","src":{"c":"Sahih Muslim","r":"2664","u":"https://sunnah.com/muslim:2664","g":"Sahih"}},{"id":"dua_no_harm_purification","k":2,"t":"ما تقوله للمريض","m":"لا بأس، طهورٌ إن شاء الله.","o":"وردَ أنّه كان يُقال عند زيارة المريض.","q":null,"ar":"لَا بَأْسَ، طَهُورٌ إِنْ شَاءَ اللَّهُ","tr":"La ba'sa, tahurun in sha'a Allah","src":{"c":"Sahih al-Bukhari","r":"5656","u":"https://sunnah.com/bukhari:5656","g":"Sahih"}},{"id":"dua_asking_for_healing","k":2,"t":"تسأل الله أن يشفيه","m":"أسأل الله العظيم، ربّ العرش العظيم، أن يشفيك.","o":"وردَ أنّه كان يُقال عند زيارة المريض.","q":null,"ar":"أَسْأَلُ اللَّهَ الْعَظِيمَ، رَبَّ الْعَرْشِ الْعَظِيمِ، أَنْ يَشْفِيَكَ","tr":"As'alu Allaha l-'Azim, Rabba l-'arshi l-'azim, an yashfiyak","src":{"c":"Sunan Abi Dawud","r":"3106","u":"https://sunnah.com/abudawud:3106","g":"Sahih (per al-Albani)"}},{"id":"dua_pain_in_the_body","k":2,"t":"حين يؤلمك موضعٌ من جسدك","m":"أعوذ بالله وقدرته من شرّ ما أجد وأحاذر.","o":"وردَ أن تضع يدك على موضع الألم وتقول «بسم الله» ثلاثًا، ثمّ تقول هذا.","q":null,"ar":"أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ","tr":"A'udhu billahi wa qudratihi min sharri ma ajidu wa uhadhir","src":{"c":"Sahih Muslim","r":"2202","u":"https://sunnah.com/muslim:2202","g":"Sahih"}},{"id":"dua_gathering_expiation","k":3,"t":"عند القيام من المجلس","m":"سبحانك اللهمّ وبحمدك، أشهد أن لا إله إلّا أنت، أستغفرك وأتوب إليك.","o":"وردَ أنّه كان يُقال عند القيام من المجلس.","q":null,"ar":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","tr":"Subhanaka Allahumma wa bihamdik, ash-hadu an la ilaha illa ant, astaghfiruka wa atubu ilayk","src":{"c":"Sunan Abi Dawud","r":"4859","u":"https://sunnah.com/abudawud:4859","g":"Hasan Sahih (per al-Albani)"}},{"id":"dua_istighfar_of_the_living","k":3,"t":"تسأل الله أن يغفر لك","m":"أستغفر الله العظيم الذي لا إله إلّا هو، الحيّ القيّوم، وأتوب إليه.","o":"يمكن أن يُقال متى شئت. ولم يحدّد له المصدر وقتًا معيّنًا.","q":null,"ar":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ","tr":"Astaghfiru Allaha l-'Azima lladhi la ilaha illa huwa l-Hayyu l-Qayyumu wa atubu ilayh","src":{"c":"Jami' at-Tirmidhi","r":"3577","u":"https://sunnah.com/tirmidhi:3577","g":"Hasan (per Darussalam)"}},{"id":"dua_hundred_times_in_a_sitting","k":3,"t":"أكثر ما كان يقوله ﷺ","m":"ربِّ اغفر لي وتُب عليّ، إنّك أنت التوّاب الغفور.","o":"وردَ أنّه ﷺ كان يقوله في المجلس الواحد.","q":null,"ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ","tr":"Rabbi ghfir li wa tub 'alayya innaka anta t-Tawwabu l-Ghafur","src":{"c":"Jami' at-Tirmidhi","r":"3434","u":"https://sunnah.com/tirmidhi:3434","g":"Sahih (per Darussalam)"}},{"id":"dua_subhanallahi_wa_bihamdih","k":3,"t":"مئة مرّة في اليوم","m":"سبحان الله وبحمده.","o":"وردَ أنّه يُقال في اليوم.","q":null,"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","tr":"Subhana Allahi wa bihamdih","src":{"c":"Sahih Muslim","r":"2691","u":"https://sunnah.com/muslim:2691","g":"Sahih"}},{"id":"dua_by_you_we_enter_the_morning","k":4,"t":"تفتح به يومك","m":"اللهمّ بك أصبحنا، وبك أمسينا، وبك نحيا، وبك نموت، وإليك النشور.","o":"وردَ أنّه كان يُقال في الصباح ثمّ في المساء.","q":null,"ar":"اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ","tr":"Allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namut, wa ilayka n-nushur","src":{"c":"Sunan Abi Dawud","r":"5068","u":"https://sunnah.com/abudawud:5068","g":"Sahih (per al-Albani)"}},{"id":"dua_pardon_and_wellbeing","k":4,"t":"تسأل الحفظ من كلّ جهة","m":"اللهمّ إنّي أسألك العافية في الدنيا والآخرة. اللهمّ إنّي أسألك العفو والعافية في ديني ودنيايَ وأهلي ومالي. اللهمّ استُر عوراتي، وآمِن روعاتي. اللهمّ احفظني من بين يديّ، ومن خلفي، وعن يميني، وعن شمالي، ومن فوقي، وأعوذ بعظمتك أن أُغتال من تحتي.","o":"وردَ أنّه كان يُقال في الصباح ثمّ في المساء.","q":null,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي","tr":"Allahumma inni as'aluka l-'afiyata fi d-dunya wa l-akhirah, Allahumma inni as'aluka l-'afwa wa l-'afiyata fi dini wa dunyaya wa ahli wa mali, Allahumma stur 'awrati wa amin raw'ati, Allahumma hfazni min bayni yadayya wa min khalfi wa 'an yamini wa 'an shimali wa min fawqi, wa a'udhu bi 'azamatika an ughtala min tahti","src":{"c":"Sunan Abi Dawud","r":"5074","u":"https://sunnah.com/abudawud:5074","g":"Sahih (per al-Albani)"}},{"id":"dua_protecting_children","k":5,"t":"تُعوّذ ولدك بالله","m":"أُعيذكما بكلمات الله التامّة، من كلّ شيطانٍ وهامّة، ومن كلّ عينٍ لامّة.","o":"وردَ أنّه ﷺ كان يعوّذ به الحسن والحسين.","q":null,"ar":"أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","tr":"U'idhukuma bi kalimati Allahi t-tammah, min kulli shaytanin wa hammah, wa min kulli 'aynin lammah","src":{"c":"Jami' at-Tirmidhi","r":"2060","u":"https://sunnah.com/tirmidhi:2060","g":"Sahih (per Darussalam)"}},{"id":"dua_blessing_the_newlywed","k":5,"t":"ما تقوله في العرس","m":"بارك الله لك، وبارك عليك، وجمع بينكما في خير.","o":"وردَ أنّه كان يُقال لمن تزوّج.","q":null,"ar":"بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ","tr":"Baraka Allahu lak, wa baraka 'alayk, wa jama'a baynakuma fi khayr","src":{"c":"Sunan Abi Dawud","r":"2130","u":"https://sunnah.com/abudawud:2130","g":"Sahih (per al-Albani)"}},{"id":"dua_asking_for_her_good","k":5,"t":"في بداية الزواج","m":"اللهمّ إنّي أسألك خيرها، وخير ما جبلتها عليه، وأعوذ بك من شرّها، وشرّ ما جبلتها عليه.","o":"وردَ أنّه كان يُقال في بداية الزواج.","q":null,"ar":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ","tr":"Allahumma inni as'aluka khayraha, wa khayra ma jabaltaha 'alayh, wa a'udhu bika min sharriha, wa sharri ma jabaltaha 'alayh","src":{"c":"Sunan Abi Dawud","r":"2160","u":"https://sunnah.com/abudawud:2160","g":"Hasan (per al-Albani)"}},{"id":"dua_suffice_me_with_the_lawful","k":6,"t":"حين يثقلك الدَّين","m":"اللهمّ اكفني بحلالك عن حرامك، وأغنني بفضلك عمّن سواك.","o":"وردَ أنّه كان يُعلَّم لمن أثقله الدَّين.","q":null,"ar":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","tr":"Allahumma kfini bi halalika 'an haramik, wa aghnini bi fadlika 'amman siwak","src":{"c":"Jami' at-Tirmidhi","r":"3563","u":"https://sunnah.com/tirmidhi:3563","g":"Hasan (per Darussalam)"}},{"id":"dua_thanking_the_lender","k":6,"t":"حين تردّ قرضًا","m":"بارك الله لك في أهلك ومالك. إنّما جزاء السلف الحمد والأداء.","o":"وردَ أنّه كان يُقال لمن أقرضك، بعد ردّ القرض.","q":null,"ar":"بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالْأَدَاءُ","tr":"Baraka Allahu laka fi ahlika wa malik, innama jaza'u s-salafi l-hamdu wa l-ada'","src":{"c":"Sunan an-Nasa'i","r":"4683","u":"https://sunnah.com/nasai:4683","g":"Hasan (per Darussalam)"}},{"id":"dua_entrusting_the_traveller","k":7,"t":"حين تودّع مسافرًا","m":"أستودع الله دينك، وأمانتك، وخواتيم عملك.","o":"وردَ أنّه كان يُقال لمن يريد السفر.","q":null,"ar":"أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ","tr":"Astawdi'u Allaha dinaka wa amanatak, wa khawatima 'amalik","src":{"c":"Sunan Abi Dawud","r":"2600","u":"https://sunnah.com/abudawud:2600","g":"Sahih (per al-Albani)"}},{"id":"dua_stopping_somewhere","k":7,"t":"حين تنزل مكانًا جديدًا","m":"أعوذ بكلمات الله التامّات من شرّ ما خلق.","o":"وردَ أنّه كان يُقال عند النزول في مكان أو الإقامة فيه.","q":null,"ar":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","tr":"A'udhu bi kalimati Allahi t-tammati min sharri ma khalaq","src":{"c":"Sahih Muslim","r":"2708b","u":"https://sunnah.com/muslim:2708b","g":"Sahih"}},{"id":"dua_praise_on_waking","k":8,"t":"حين تفتح عينيك","m":"الحمد لله الذي أحيانا بعد ما أماتنا، وإليه النشور.","o":"وردَ أنّه كان يُقال عند الاستيقاظ.","q":null,"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","tr":"Al-hamdu lillahi lladhi ahyana ba'da ma amatana wa ilayhi n-nushur","src":{"c":"Sahih al-Bukhari","r":"7394","u":"https://sunnah.com/bukhari:7394","g":"Sahih"}},{"id":"dua_soul_returned","k":8,"t":"تستيقظ معافى","m":"الحمد لله الذي عافاني في جسدي، وردّ عليّ روحي، وأذن لي بذكره.","o":"وردَ أنّه كان يُقال عند الاستيقاظ.","q":null,"ar":"الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي وَرَدَّ عَلَيَّ رُوحِي وَأَذِنَ لِي بِذِكْرِهِ","tr":"Al-hamdu lillahi lladhi 'afani fi jasadi wa radda 'alayya ruhi wa adhina li bi dhikrih","src":{"c":"Jami' at-Tirmidhi","r":"3401","u":"https://sunnah.com/tirmidhi:3401","g":"Sahih (per Darussalam)"}},{"id":"dua_laying_down_my_side","k":8,"t":"حين تضع جنبك للنوم","m":"باسمك ربّي وضعت جنبي، وبك أرفعه. فإن أمسكت نفسي فارحمها، وإن أرسلتها فاحفظها بما تحفظ به عبادك الصالحين.","o":"وردَ أنّه كان يُقال عند الاضطجاع للنوم.","q":null,"ar":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ","tr":"Bismika Rabbi wada'tu janbi, wa bika arfa'uh, fa in amsakta nafsi farhamha, wa in arsaltaha fahfazha bima tahfazu bihi 'ibadaka s-salihin","src":{"c":"Sahih al-Bukhari","r":"6320","u":"https://sunnah.com/bukhari:6320","g":"Sahih"}},{"id":"dua_in_your_name_i_die_and_live","k":8,"t":"سطران قبل النوم","m":"باسمك اللهمّ أموت وأحيا.","o":"وردَ أنّه كان يُقال عند الاضطجاع للنوم.","q":null,"ar":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","tr":"Bismika Allahumma amutu wa ahya","src":{"c":"Sahih al-Bukhari","r":"6324","u":"https://sunnah.com/bukhari:6324","g":"Sahih"}},{"id":"dua_fed_and_sheltered","k":8,"t":"تعدّ نِعم يومك","m":"الحمد لله الذي أطعمنا وسقانا، وكفانا، وآوانا. فكم ممّن لا كافيَ له ولا مُؤويَ.","o":"وردَ أنّه كان يُقال عند الاضطجاع للنوم.","q":null,"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ","tr":"Al-hamdu lillahi lladhi at'amana wa saqana, wa kafana, wa awana, fakam mimman la kafiya lahu wa la mu'wi","src":{"c":"Sahih Muslim","r":"2715","u":"https://sunnah.com/muslim:2715","g":"Sahih"}},{"id":"dua_after_ablution","k":9,"t":"حين تُتمّ وضوءك","m":"أشهد أن لا إله إلّا الله وحده لا شريك له، وأشهد أنّ محمّدًا عبده ورسوله.","o":"وردَ أنّه كان يُقال بعد إتمام الوضوء.","q":null,"ar":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","tr":"Ash-hadu an la ilaha illa Allahu wahdahu la sharika lah, wa ash-hadu anna Muhammadan 'abduhu wa rasuluh","src":{"c":"Sahih Muslim","r":"234b","u":"https://sunnah.com/muslim:234b","g":"Sahih"}},{"id":"dua_leaving_the_home","k":9,"t":"حين تخرج من الباب","m":"بسم الله، توكّلت على الله، ولا حول ولا قوّة إلّا بالله.","o":"وردَ أنّه كان يُقال عند الخروج من المنزل.","q":null,"ar":"بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Bismillah, tawakkaltu 'ala Allah, wa la hawla wa la quwwata illa billah","src":{"c":"Sunan Abi Dawud","r":"5095","u":"https://sunnah.com/abudawud:5095","g":"Sahih (per al-Albani)"}},{"id":"dua_breaking_the_fast","k":9,"t":"حين تُفطر","m":"ذهب الظمأ، وابتلّت العروق، وثبت الأجر إن شاء الله.","o":"وردَ أنّه ﷺ كان يقوله عند إفطاره.","q":null,"ar":"ذَهَبَ الظَّمَأُ، وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","tr":"Dhahaba z-zama'u, wa btallati l-'uruq, wa thabata l-ajru in sha'a Allah","src":{"c":"Sunan Abi Dawud","r":"2357","u":"https://sunnah.com/abudawud:2357","g":"Hasan (per al-Albani)"}},{"id":"dua_after_the_meal","k":9,"t":"بعد أن تطعم","m":"الحمد لله الذي أطعمني هذا ورزقنيه، من غير حولٍ منّي ولا قوّة.","o":"وردَ أنّه كان يُقال بعد الطعام.","q":null,"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","tr":"Al-hamdu lillahi lladhi at'amani hadha wa razaqanih min ghayri hawlin minni wa la quwwah","src":{"c":"Jami' at-Tirmidhi","r":"3458","u":"https://sunnah.com/tirmidhi:3458","g":"Hasan (per Darussalam)"}},{"id":"dua_when_angry","k":9,"t":"حين يشتدّ غضبك","m":"أعوذ بالله من الشيطان الرجيم.","o":"وردَ أنّه ما يُقال إذا استبدّ الغضب.","q":null,"ar":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":"A'udhu billahi mina sh-shaytani r-rajim","src":{"c":"Sahih al-Bukhari","r":"6115","u":"https://sunnah.com/bukhari:6115","g":"Sahih"}},{"id":"dua_istikharah","k":10,"t":"حين لا تستطيع أن تقرّر","m":"اللهمّ إنّي أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم. فإنّك تقدر ولا أقدر، وتعلم ولا أعلم، وأنت علّام الغيوب. اللهمّ إن كنت تعلم أنّ هذا الأمر خيرٌ لي في ديني ومعاشي وعاقبة أمري، فاقدره لي ويسّره لي، ثمّ بارك لي فيه. وإن كنت تعلم أنّ هذا الأمر شرٌّ لي في ديني ومعاشي وعاقبة أمري، فاصرفه عنّي واصرفني عنه، واقدر لي الخير حيث كان، ثمّ أرضني به.","o":"وردَ أنّه كان يُعلَّم لكلّ أمرٍ تقصده، بعد رَكعتين من غير الفريضة. سمِّ حاجتك في موضع «هذا الأمر».","q":null,"ar":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ","tr":"Allahumma inni astakhiruka bi 'ilmik, wa astaqdiruka bi qudratik, wa as'aluka min fadlika l-'azim, fa innaka taqdiru wa la aqdir, wa ta'lamu wa la a'lam, wa anta 'allamu l-ghuyub. Allahumma in kunta ta'lamu anna hadha l-amra khayrun li fi dini wa ma'ashi wa 'aqibati amri faqdurhu li wa yassirhu li thumma barik li fih. Wa in kunta ta'lamu anna hadha l-amra sharrun li fi dini wa ma'ashi wa 'aqibati amri fasrifhu 'anni wasrifni 'anh, waqdur li l-khayra haythu kana thumma ardini bih","src":{"c":"Sahih al-Bukhari","r":"1166","u":"https://sunnah.com/bukhari:1166","g":"Sahih"}},{"id":"dua_setting_out_on_a_journey","k":7,"t":"عند الانطلاق في سفر","m":"سبحان الذي سخّر لنا هذا وما كنّا له مقرنين، وإنّا إلى ربّنا لمنقلبون. اللهمّ إنّا نسألك في سفرنا هذا البرّ والتقوى، ومن العمل ما ترضى. اللهمّ هوّن علينا سفرنا هذا، واطوِ عنّا بعده. اللهمّ أنت الصاحب في السفر، والخليفة في الأهل. اللهمّ إنّي أعوذ بك من وعثاء السفر، وكآبة المنظر، وسوء المنقلب في المال والأهل.","o":"وردَ أنّه ﷺ كان يقوله إذا استوى على راحلته خارجًا إلى سفر، بعد أن يكبّر ثلاثًا. وإذا رجع قالهنّ وزاد: آيبون تائبون عابدون لربّنا حامدون.","q":null,"ar":"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالأَهْلِ","tr":"Subhana lladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila Rabbina la-munqalibun. Allahumma inna nas'aluka fi safarina hadha l-birra wa t-taqwa, wa mina l-'amali ma tarda. Allahumma hawwin 'alayna safarana hadha, watwi 'anna bu'dah. Allahumma anta s-sahibu fi s-safar, wa l-khalifatu fi l-ahl. Allahumma inni a'udhu bika min wa'tha'i s-safar, wa ka'abati l-manzar, wa su'i l-munqalabi fi l-mali wa l-ahl","src":{"c":"Sahih Muslim","r":"1342","u":"https://sunnah.com/muslim:1342","g":"Sahih"}},{"id":"dua_entering_the_mosque","k":9,"t":"دخول المسجد","m":"اللهمّ افتح لي أبواب رحمتك.","o":"وردَ أنّه يُقال عند دخول المسجد. وفي الحديث نفسه سؤال الله من فضله عند الخروج منه.","q":null,"ar":"اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tr":"Allahumma ftah li abwaba rahmatik","src":{"c":"Sahih Muslim","r":"713a","u":"https://sunnah.com/muslim:713a","g":"Sahih"}},{"id":"dua_laylat_al_qadr","k":3,"t":"في ليلة القدر","m":"اللهمّ إنّك عفوّ تحبّ العفو فاعفُ عنّي.","o":"وردَ أنّ النبيّ ﷺ علّمه عائشة حين سألته ماذا تقول إن وافقت ليلة القدر.","q":null,"ar":"اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","tr":"Allahumma innaka 'Afuwwun tuhibbu l-'afwa fa'fu 'anni","src":{"c":"Sunan Ibn Majah","r":"3850","u":"https://sunnah.com/ibnmajah:3850","g":"Sahih (per Darussalam)"}},{"id":"dua_after_the_adhan","k":9,"t":"بعد الأذان","m":"اللهمّ ربّ هذه الدعوة التامّة والصلاة القائمة، آتِ محمّدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته.","o":"وردَ أنّه يُقال عند سماع النداء.","q":null,"ar":"اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلاَةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ","tr":"Allahumma Rabba hadhihi d-da'wati t-tammah, wa s-salati l-qa'imah, ati Muhammadan al-wasilata wa l-fadilah, wab'ath-hu maqaman mahmudan alladhi wa'adtah","src":{"c":"Sahih al-Bukhari","r":"614","u":"https://sunnah.com/bukhari:614","g":"Sahih"}},{"id":"dua_after_the_prayer","k":9,"t":"عند الفراغ من الصلاة","m":"اللهمّ أنت السلام ومنك السلام، تباركت ذا الجلال والإكرام.","o":"وردَ أنّه ﷺ كان يقوله إذا انصرف من صلاته، بعد أن يستغفر ثلاثًا.","q":null,"ar":"اللَّهُمَّ أَنْتَ السَّلاَمُ وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ ذَا الْجَلاَلِ وَالإِكْرَامِ","tr":"Allahumma anta s-salamu wa minka s-salam, tabarakta dha l-jalali wa l-ikram","src":{"c":"Sahih Muslim","r":"591","u":"https://sunnah.com/muslim:591","g":"Sahih"}},{"id":"dua_for_those_before_us","k":3,"t":"لمن رحلوا قبلنا","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[59,10,10],"ar":null,"tr":"Rabbana ghfir lana wa li-ikhwanina lladhina sabaquna bi-l-iman, wa la taj'al fi qulubina ghillan li-lladhina amanu, Rabbana innaka Ra'ufun Rahim","src":null},{"id":"dua_offspring_zakariyya","k":5,"t":"سؤال الله الولد","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[3,38,38],"ar":null,"tr":"Rabbi hab li min ladunka dhurriyyatan tayyibah, innaka sami'u d-du'a'","src":null},{"id":"dua_gratitude_sulayman","k":9,"t":"سؤال الله العون على الشكر","m":null,"o":"سجّل القرآن هذا الدعاء. ولم يحدّد له مصدرٌ وقتًا ولا عددًا من التكرار، فيمكن أن يُقال متى شئت.","q":[27,19,19],"ar":null,"tr":"Rabbi awzi'ni an ashkura ni'mataka llati an'amta 'alayya wa 'ala walidayya wa an a'mala salihan tardah, wa adkhilni bi-rahmatika fi 'ibadika s-salihin","src":null}],"prophets":["MUSA","IBRAHIM","YUSUF","NUH","ADAM","YUNUS","AYYUB","MARYAM","ISA","DAWUD","SULAYMAN","YAQUB","SHUAYB","ZAKARIYYA","YAHYA","HUD","ISMAIL"],"reflections":[{"id":"musa_love_cast","t":"محبوب قبل أن يدري","b":"تابوت على نهر ليست خطة تختارها أمّ. يخبر الله موسى أنه ألقى عليه محبّة منه، وأنه رُبِّي على عينه سبحانه. لم يكن التيار في يوم من الأيام هو المتحكّم.","th":[0],"p":0,"q":[20,39]},{"id":"musa_mother_river","t":"أشقّ أمر","b":"قيل لها أن تضع وليدها في الماء، وقيل لها في النَّفَس ذاته ألّا تخاف وألّا تحزن. جاء الأمر أولًا وسار الطمأنينة معه لا بعده. ما الذي يُطلب منك أن تتركه؟","th":[0],"p":0,"q":[28,7]},{"id":"musa_mother_heart","t":"قلبٌ رُبِط على مكانه","b":"فرغ قلبها من كل شيء إلا منه. يذكر القرآن أن الله ربط على قلبها لئلا تُفشي السرّ. حتى قوّة الصمت أُعطيت لها ولم تستدعِها من نفسها.","th":[0],"p":0,"q":[28,10]},{"id":"musa_untie_my_tongue","t":"طلب متّسعًا","b":"أُرسل إلى أقوى رجل في زمانه، فلم يسأل قوّة. سأل صدرًا أوسع، وأمرًا أيسر، ولسانًا لا يخذله. اسأل ما تحتاجه المهمة فعلًا.","th":[0],"p":0,"q":[20,25]},{"id":"musa_i_am_with_you","t":"قبل أن يصل أصلًا","b":"قال موسى وهارون إنهما يخافان أن يبطش فرعون أولًا. لم يكن الجواب خطة بل معيّة: لا تخافا، إنني معكما أسمع وأرى. لم يُوبَّخ الخوف. أُجيب عنه.","th":[0],"p":0,"q":[20,46]},{"id":"musa_sea_ahead","t":"ماء أمامهم وجيش خلفهم","b":"أحصى قومه الاحتمالات بصوت عالٍ وأعلنوا أن اللحاق بهم مؤكّد. صحّح موسى الحساب لا الخوف: إن معي ربي سيهدين. انفلق البحر بعد هذا اليقين لا قبله.","th":[0],"p":0,"q":[26,62]},{"id":"musa_madyan_shade","t":"فقيرٌ غير خجل","b":"غريبًا في مدين بلا شيء، سقى لغيره أولًا، ثم جلس في الظل وقال لربه إنه لما أنزل إليه من خير فقير. وفي يومه ذاك صار له عمل ومأوى وأهل.","th":[0],"p":0,"q":[28,24]},{"id":"musa_pray_for_my_remembrance","t":"لماذا وُجدت الصلاة","b":"أول ما قيل لموسى عند النار لم يكن مهمّة. كان تعريف الله بنفسه، ثم أمر بإقامة الصلاة لذكره. الصلاة ليست عملًا يُضاف إلى يومك، بل هي السبب في أن اليوم لك.","th":[0],"p":0,"q":[20,14]},{"id":"musa_show_me","t":"السؤال الذي أُذن له فيه","b":"سأل أن يراه. كان الجواب لا، ثم اندكّ الجبل من تجلٍّ واحد وخرّ موسى صعقًا. ليس كل منع عتابًا. بعضه رحمة ما كنت لتحتملها لو أُعطيتها.","th":[0],"p":0,"q":[7,143]},{"id":"musa_hastened","t":"بكّر لأنه أراد","b":"حين سُئل لماذا سبق قومه، قال إنهم على أثره وإنه عجل إلى ربه ليرضى. الشوق الذي يستعجل عبادة في ذاته.","th":[0],"p":0,"q":[20,84]},{"id":"musa_khidr_teach_me","t":"نبيّ طلب أن يكون تلميذًا","b":"كان موسى قد كلّم الله، ومع ذلك استأذن أن يتّبع معلّمًا ليتعلّم. لا أحد يكبر على أن يتعلّم. من يمكنه أن يعلّمك شيئًا هذا الشهر؟","th":[0],"p":0,"q":[18,66]},{"id":"musa_tuwa_sandals","t":"اخلع نعليك","b":"قبل الرسالة وقبل المعجزة جاء توجيه عن قدميه. كان واقفًا في وادٍ مقدّس وكان عليه أن يعلم. بعض الأماكن وبعض اللحظات تطلب أن تدخلها على نحوٍ آخر.","th":[0],"p":0,"q":[20,12]},{"id":"musa_strengthen_arm_brother","t":"طلب أخاه","b":"لم يطلب موسى ذراعًا أقوى. طلب هارون إلى جانبه، فقيل له إن عضده سيُشدّ بأخيه. العون ليس صورة أضعف من القوّة. هو في الغالب الصورة التي تأتي بها القوّة.","th":[0],"p":0,"q":[28,35]},{"id":"musa_you_are_our_protector","t":"بعد أسوأ أسبوع","b":"فعل قومه الشيء الوحيد الذي حذّرهم منه، وسقط منهم سبعون. لم يدافع موسى عنهم. سمّى الله وليَّهم، وسأل المغفرة والرحمة، ووقف عند ذلك.","th":[0],"p":0,"q":[7,155]},{"id":"musa_gentle_speech","t":"قولا له قولًا ليّنًا","b":"جاء التوجيه في شأن فرعون، وهو رجل ادّعى الألوهية، أن يُقال له قول ليّن لعلّه يتذكّر. إذا كان ذلك الطاغية أهلًا للين، فكذلك من تجادله الليلة.","th":[0],"p":0,"q":[20,44]},{"id":"ibrahim_satisfy_my_heart","t":"ليس شكًّا. بل طمأنينة.","b":"سأل أن يُريه كيف يحيي الموتى. وحين سُئل أولم تؤمن، قال بلى، ولكن ليطمئن قلبه. أن تريد أن تشعر به ليس مثل ألّا تؤمن به.","th":[0],"p":1,"q":[2,260]},{"id":"ibrahim_star_moon_sun","t":"لا شيء يأفل","b":"نظر إلى كوكب ثم إلى قمر ثم إلى شمس، وتخلّى عن كل واحد حين أفل. ثم وجّه وجهه للذي فطر السماوات والأرض. الذي بنيتَ عليه سكينتك، هل يأفل؟","th":[0],"p":1,"q":[6,79]},{"id":"ibrahim_fire_cool","t":"لم تُطفأ النار","b":"بنوها وألقوه فيها، وجاء الأمر إلى النار نفسها: كوني بردًا وسلامًا. أحيانًا لا يُرفع الذي يهدّدك، بل يُقال له فقط: كفّ عن الإحراق.","th":[0],"p":1,"q":[21,69]},{"id":"ibrahim_dream_sacrifice","t":"أخبر ابنه أولًا","b":"لم يمضِ إبراهيم في الرؤيا وحده. أخبر ابنه وسأله ماذا يرى، فأجاب الفتى أنه سيجده صابرًا. حملها اثنان، ولم ينكسر واحد منهما.","th":[0],"p":1,"q":[37,102]},{"id":"ibrahim_ask_for_righteous","t":"عمرٌ كامل من السؤال","b":"الطلب الوحيد الذي سأله لنفسه، كما يسجّله القرآن، ولد صالح. انتظر عقودًا. لم يكن التأخير رفضًا قط، والجواب بقي بعده في كل جيل.","th":[0],"p":1,"q":[37,100]},{"id":"ibrahim_barren_valley","t":"وادٍ لا ينبت فيه شيء","b":"ترك أهله حيث لا زرع، ودعا أن تهوي إليهم أفئدة الناس وأن يُرزقوا من الثمرات. اليوم يطوف بذلك الوادي الملايين، ولم يكن يرى شيئًا من ذلك حين دعا.","th":[0],"p":1,"q":[14,37]},{"id":"ibrahim_establisher_of_prayer","t":"اجعلني مقيمًا للصلاة","b":"شيخ في آخر عمر من الطاعة يسأل أن يُجعل من مقيمي الصلاة، ويسألها لذريّته أيضًا. لم يفترض يومًا أن الثبات صار ملكًا له.","th":[0],"p":1,"q":[14,40]},{"id":"ibrahim_accept_from_us","t":"يبني ويتضرّع","b":"وهو يرفع القواعد من البيت مع ابنه، لم يُعجب بالعمل. سأل الله أن يتقبّل منهما. اعمل العمل، ثم اسأل أن يُقبل. النصف الثاني ليس اختياريًا.","th":[0],"p":1,"q":[2,127]},{"id":"ibrahim_mention_of_truth","t":"ذكرٌ لم يصنعه بنفسه","b":"سأل لسان صدق في الآخرين. وكل صلاة تُقام في الإسلام منذ ذلك الحين تحمل اسمه. سأل، فأُجيب بعملة لم يمسّها بيده قط.","th":[0],"p":1,"q":[26,84]},{"id":"ibrahim_a_nation_alone","t":"رجل واحد عُدّ أمّة","b":"يصف القرآن إبراهيم بأنه كان أمّة قانتًا لله حنيفًا. حين تجد نفسك الوحيد في الغرفة الذي يثبت على الحق، فهناك سابقة.","th":[0],"p":1,"q":[16,120]},{"id":"ibrahim_excellent_pattern","t":"ما الذي جعله واضحًا","b":"يقدّم القرآن إبراهيم أسوةً، ويشير تحديدًا إلى صراحته في التبرّؤ ممّا يعبده قومه. الوضوح هو الذي يُمدح. لا العداوة. الوضوح.","th":[0],"p":1,"q":[60,4]},{"id":"ibrahim_forgiveness_for_father","t":"هُدِّد فقال: سلام","b":"توعّده أبوه بالرجم وأمره أن يهجره مليًّا. فأجاب إبراهيم بالسلام ووعدٍ أن يستغفر له. ألّا تردّ القسوة انضباطٌ لا طبع.","th":[0],"p":1,"q":[19,47]},{"id":"yusuf_dream_eleven_stars","t":"احكِ لمن يستحق","b":"رأى غلام أحد عشر كوكبًا والشمس والقمر ساجدين له. وكان أول توجيه من أبيه أن يكتمها. ليس كل خير يُعطى لك آمنًا في كل مجلس.","th":[0],"p":2,"q":[12,4]},{"id":"yusuf_maadhallah","t":"كلمتان في غرفة مغلقة","b":"أبواب مغلّقة، ولا شهود، وكل شيء مهيّأ. الذي قاله إنه يعوذ بالله. لم يفاوضها. أخرج الأمر من يده في الحال.","th":[0],"p":2,"q":[12,23]},{"id":"yusuf_prison_preferred","t":"اختار الزنزانة","b":"قال لربه صراحة إن السجن أحبّ إليه ممّا يدعونه إليه، ثم أقرّ أنه لا يستطيع الانصراف عنهنّ إلا بعون. القوّة سُئلت ولم تُدّعَ.","th":[0],"p":2,"q":[12,33]},{"id":"yusuf_forgotten_in_prison","t":"اذكرني عند ربّك","b":"طلب من رفيق سجنه أن يذكره، فنسي الرجل، ومضت سنون. لم يُعاقب لأنه طلب. لكن الفرج حين جاء أخيرًا جاء من حيث لم يطلب.","th":[0],"p":2,"q":[12,42]},{"id":"yusuf_the_soul_commands","t":"لم يثق بنفسه","b":"في ذروة تبرئته رفض يوسف أن يزكّي نفسه، وقال إن النفس أمّارة بالسوء إلا ما رحم ربه. أكثر الناس أمانًا من لا يفترض في نفسه الأمان أبدًا.","th":[0],"p":2,"q":[12,53]},{"id":"yusuf_taqwa_and_sabr","t":"اتّقِ الله واثبت","b":"حين عرفه أخيرًا إخوته الذين ألقوه في الجبّ، سمّى الشيئين اللذين حملاه: التقوى والصبر. والله لا يضيع أجر المحسنين.","th":[0],"p":2,"q":[12,90]},{"id":"yusuf_no_blame_today","t":"الحكم الذي كان يستطيع إصداره","b":"كانت السلطة بيده والدليل معه والناس شهود. الذي قاله: لا تثريب عليكم اليوم. العفو أعلى صوتًا حين يكون البديل متاحًا تمامًا.","th":[0],"p":2,"q":[12,92]},{"id":"yusuf_cause_me_to_die_muslim","t":"الأمنية في القمة","b":"بعد اللقاء وردّ المكانة وتولّي خزائن مصر، كان دعاؤه أن يُتوفّى مسلمًا ويُلحق بالصالحين. لم يسأل أن يبقى له شيء من ذلك.","th":[0],"p":2,"q":[12,101]},{"id":"nuh_istighfar_rain","t":"استغفروا تُفتح السماء","b":"أمر نوح قومه أن يستغفروا ربهم، ثم عدّد ما يترتّب على ذلك: مطر غزير، ومال، وبنون، وجنّات، وأنهار. قُدّم الاستغفار حلًّا عمليًّا لا خيارًا تقيًّا.","th":[0],"p":3,"q":[71,10]},{"id":"nuh_board_in_the_name","t":"مجراها ومرساها","b":"أمرهم أن يركبوا باسم الله، وذكر في النَّفَس ذاته الجريان والرسوّ. أن تبدأ أمرًا باسمه ليس شكليّة. هو بيان بمن يمسك الدفّة.","th":[0],"p":3,"q":[11,41]},{"id":"nuh_overpowered_help_me","t":"قرون ثم أربع كلمات","b":"بعد عمر من السخرية كان دعاؤه قصيرًا جدًّا: أني مغلوب فانتصر. يحقّ لك أن تنفد كلماتك. قل القصيرة.","th":[0],"p":3,"q":[54,10]},{"id":"nuh_the_son","t":"الذي لم يستطع إنقاذه","b":"نادى ابنه أن يركب معه، فاختار الابن جبلًا. لا عاصم يومئذ إلا من رحم الله. الهداية ليست ميراثًا يورّثه الأب.","th":[0],"p":3,"q":[11,43]},{"id":"nuh_a_thousand_years","t":"ألفٌ إلا خمسين","b":"لبث في قوم لا يسمعون تسعة قرون ونصفًا. مهما كان الذي تحتمله، فأنت لم تبلغ بعد حدّ ما حمله عبد من عباد الله.","th":[0],"p":3,"q":[29,14]},{"id":"adam_taught_the_names","t":"أول عطاء كان علمًا","b":"قبل أن يُؤمر الملائكة بالسجود، عُلِّم آدم الأسماء كلها. فُتح شرف الإنسان بأن عُلِّم. ما تتعلّمه عن قصد هذا الأسبوع ليس مشروعًا جانبيًّا.","th":[0],"p":4,"q":[2,31]},{"id":"adam_we_wronged_ourselves","t":"الكلمات التي بدأت كل شيء من جديد","b":"لم يشرح آدم وزوجه ولم يهوّنا ولم يُلقيا اللوم. قالا إنهما ظلما أنفسهما وإنهما بلا مغفرة ورحمة من الخاسرين. هذه صورة التوبة التي تعمل.","th":[0],"p":4,"q":[7,23]},{"id":"adam_received_words","t":"أُعطي الكلمات نفسها","b":"تلقّى آدم من ربه كلمات، فتاب عليه. حتى لغة الرجوع كانت هبة. إن لم تعرف كيف تعود، فاسأل أن يُدلّك.","th":[0],"p":4,"q":[2,37]},{"id":"adam_he_forgot","t":"النسيان جزء من التصميم","b":"يذكر القرآن أن عهدًا أُخذ على آدم فنسي ولم يُوجد له عزم. نسيانك ليس جديدًا ولا مسقطًا لك. ابنِ التذكيرات بدل الشعور بالذنب.","th":[0],"p":4,"q":[20,115]},{"id":"adam_children_honoured","t":"حُملوا في البرّ والبحر","b":"يقول الله إنه كرّم بني آدم وحملهم في البرّ والبحر ورزقهم من الطيّبات وفضّلهم. مهما قيل لك عن قيمتك، فهناك بيان أقدم مسجّل.","th":[0],"p":4,"q":[17,70]},{"id":"yunus_in_the_darkness","t":"دعاء من داخل الظلمة","b":"ظلمات متراكمة وبلا مساومة. أعلن أن لا إله إلا هو، ونزّهه، وعدّ نفسه من الظالمين. لم يطلب شيئًا، وكان ذلك هو الدعاء الذي استُجيب.","th":[0],"p":5,"q":[21,87]},{"id":"yunus_we_save_the_believers","t":"وكذلك ننجي","b":"استجاب الله له ونجّاه من الغمّ، ثم أضاف أن كذلك ينجّي المؤمنين. جاء الإنقاذ مذكورًا كقاعدة لا كاستثناء.","th":[0],"p":5,"q":[21,88]},{"id":"yunus_had_he_not_glorified","t":"رصيد كان قد أودعه","b":"يقول القرآن إنه لولا أنه كان من المسبّحين للبث في بطنه إلى يوم يُبعثون. الذكر الذي تحفظه في وقت السعة هو الذي يطفو في الظلمة.","th":[0],"p":5,"q":[37,143]},{"id":"yunus_do_not_be_like_him","t":"اصبر ولا تنادِ","b":"قيل للنبي أن يصبر لحكم ربه وألا يكون كصاحب الحوت إذ نادى وهو مكظوم. حتى الأنبياء يُقال لهم: ليس الآن.","th":[0],"p":5,"q":[68,48]},{"id":"ayyub_harm_has_touched_me","t":"لم يطلب استرجاع شيء","b":"سنوات من المرض، والدعاء كله جملتان: أني مسّني الضرّ، وأنت أرحم الراحمين. وصف حاله ثم وصف ربه ولم يملِ نتيجة.","th":[0],"p":6,"q":[21,83]},{"id":"ayyub_we_responded","t":"وعادت إليه أسرته","b":"استجاب الله له وكشف ما به من ضرّ وآتاه أهله ومثلهم معهم رحمة وذكرى للعابدين. لم يكن الردّ إلى الحال الأول مستبعدًا يومًا.","th":[0],"p":6,"q":[21,84]},{"id":"ayyub_satan_touched_me","t":"نادى العنوان الصحيح","b":"سمّى ما يجري له بصدق، وقاله لله لا عن الله. الشكوى المرفوعة إلى فوق عبادة. والشكوى الموجّهة إلى الجانب ضجيج فقط.","th":[0],"p":6,"q":[38,41]},{"id":"ayyub_excellent_servant","t":"كيف وُصف","b":"حكم القرآن على أيوب قصير: وجدناه صابرًا، نعم العبد، إنه أوّاب. هذا ما كانت تلك السنوات كلها تُكتب به.","th":[0],"p":6,"q":[38,44]},{"id":"maryam_wish_i_had_died","t":"قالتها بصوت مسموع","b":"وحدها عند جذع النخلة، تمنّت لو ماتت قبل هذا وكانت نسيًا منسيًّا. حفظ القرآن هذه الجملة ولم يحذفها. الألم إذا قيل لله ليس كفرًا.","th":[0],"p":7,"q":[19,23]},{"id":"maryam_shake_the_trunk","t":"هزّي الجذع","b":"قيل لامرأة في مخاض أن تهزّ إليها جذع النخلة. ما كانت تستطيع تحريكه، وكان الرطب نازلًا على كل حال. افعل نصيبك مع ذلك. النصيب هو المقصود.","th":[0],"p":7,"q":[19,25]},{"id":"maryam_provision_in_the_chamber","t":"أنّى لكِ هذا","b":"كان زكريّا يجد عندها رزقًا فيسأل من أين. تقول: هو من عند الله، إن الله يرزق من يشاء بغير حساب. لم تبدُ متعجّبة منه قط.","th":[0],"p":7,"q":[3,37]},{"id":"isa_servant_of_allah","t":"أول ما قال","b":"تكلّم مولود، وأول ما أعلنه أنه عبد الله، آتاه الكتاب وجعله نبيًّا. كل ما قيل عنه بعد ذلك أُجيب عنه في جملته الأولى.","th":[0],"p":8,"q":[19,30]},{"id":"isa_prayer_and_zakah","t":"ما دمتُ حيًّا","b":"قال إنه أُوصي بالصلاة والزكاة ما دام حيًّا. لا بند تقاعد ولا موسم إعفاء. وُصفت الفريضة بأنها تمتدّ بامتداد الحياة تمامًا.","th":[0],"p":8,"q":[19,31]},{"id":"maryam_devoutly_obedient","t":"كيف قُدِّمت","b":"يقدّم القرآن مريم مثلًا للذين آمنوا ويصفها بإحصانها وتصديقها وقنوتها، لا بما فُعل بها ولا بما قيل عنها. وأنت أيضًا لست ظروفك.","th":[0],"p":7,"q":[66,12]},{"id":"dawud_mountains_repeat","t":"والجبال شاركته","b":"آتى الله داود فضلًا وأمر الجبال والطير أن يُرجّعن التسبيح معه. حين يسبّح قلب بصدق يتبيّن أنه لم يكن وحده قط.","th":[0],"p":9,"q":[34,10]},{"id":"dawud_fell_bowing","t":"فهم في الحال","b":"في اللحظة التي أدرك فيها داود أنه فُتن، استغفر وخرّ راكعًا وأناب. لا فاصل بين الإدراك والرجوع. في ذلك الفاصل تستقرّ الذنوب.","th":[0],"p":9,"q":[38,24]},{"id":"sulayman_enable_me_to_be_grateful","t":"تبسّم ثم دعا","b":"سمع نملة تحذّر جماعتها من جنده، فتبسّم ضاحكًا، ثم سأل الله أن يوزعه شكر نعمته. صار الشيء الصغير عبادة في خطوة واحدة.","th":[0],"p":10,"q":[27,19]},{"id":"sulayman_test_of_gratitude","t":"يأتي العرش فيتّهم نفسه","b":"بملك لم يبلغه أحد، كانت قراءته للحظة أن هذا من فضل ربه ليبلوه أيشكر أم يكفر. تعامل مع النعمة على أنها ورقة الاختبار.","th":[0],"p":10,"q":[27,40]},{"id":"sulayman_kingdom_after_forgiveness","t":"اغفر لي أولًا","b":"دعاؤه المشهور بملك لا ينبغي لأحد بعده يبدأ بالنصف الذي لا يكاد يُقتبس: ربّ اغفر لي. سأل المغفرة قبل أن يسأل أي شيء آخر.","th":[0],"p":10,"q":[38,35]},{"id":"yaqub_do_not_despair","t":"اذهبوا فتحسّسوا مرة أخرى","b":"شيخ كفيف فقد ابنين أرسل من بقي من بنيه للبحث، وقال لهم إنه لا ييأس من روح الله إلا القوم الكافرون. وُضع الرجاء مسألة عقيدة.","th":[0],"p":11,"q":[12,87]},{"id":"shuayb_my_success_is_from_allah","t":"ما أريد إلا الإصلاح","b":"قال شعيب لقومه إنه لا يريد إلا الإصلاح ما استطاع، وإن توفيقه إنما هو بالله. نيّة معلنة، وقدرة معترف بحدّها، ونتيجة مسلَّمة.","th":[0],"p":12,"q":[11,88]},{"id":"zakariyya_do_not_leave_me_alone","t":"لا تذرني فردًا","b":"سأل ألّا يُترك بلا وارث، ثم قال ما هو أصدق على كل حال: وأنت خير الوارثين. كان يريد الولد، وكان يعرف أيضًا من يبقى إن لم يُعطَه.","th":[0],"p":13,"q":[21,89]},{"id":"yahya_take_it_with_strength","t":"خذه بقوّة","b":"قيل ليحيى وهو صبيّ أن يأخذ الكتاب بقوّة، وأُوتي الحكم صبيًّا. لم يُسلَّم إليه الوحي ليبقى على رفّ.","th":[0],"p":14,"q":[19,12]},{"id":"hud_every_creature_by_the_forelock","t":"قلّة غير مبالية","b":"في مواجهة قوم معادين وحده، قال هود إنه توكّل على الله، وإنه ما من دابّة إلا هو آخذ بناصيتها. لم يكن في تلك الغرفة شيء خارج قبضته، والغرفة نفسها منها.","th":[0],"p":15,"q":[11,56]},{"id":"ismail_true_to_his_promise","t":"وفّى بوعده","b":"يُبرز القرآن في إسماعيل صفة فوق سائر صفاته: أنه كان صادق الوعد. ومن كل ما كان يمكن أن يُسجّل عنه، سُجّل هذا.","th":[0],"p":16,"q":[19,54]},{"id":"zakariyya_never_disappointed_in_asking","t":"لم يُخيَّب دعاؤه قط","b":"شيخًا ضعفت عظامه وابيضّ رأسه، نادى زكريا ربه في خفاء، وذكر أنه لم يُخيَّب قط حين دعاه. سأل من تاريخ طويل من الإجابة.","th":[0,4],"p":13,"q":[19,4]},{"id":"yaqub_grief_taken_to_the_right_place","t":"الشكوى إلى أهلها","b":"أخبر يعقوب أن شكواه من همّه وحزنه لا تكون إلا إلى الله، وأن عنده من العلم بالله ما ليس عندهم. لم يُخفِ حزنه ولم ينكره، بل حمله إلى من يقدر على جوابه.","th":[0,2],"p":11,"q":[12,86]},{"id":"dawud_work_in_gratitude","t":"شكرٌ يُعمَل","b":"بعد ذكر ما صُنع لسليمان، يأمر الله آل داود أن يعملوا شكرًا، ويخبر أن الشاكرين من عباده قليل. الشكر هنا عمل، لا قول فحسب.","th":[0,7],"p":9,"q":[34,13]},{"id":"mercy_do_not_despair","t":"خطابٌ لمن ذهب أبعد من الجميع","b":"تفتح الآية بمناداتهم عبادًا أسرفوا على أنفسهم، ثم تقول لهم لا تقنطوا. أشدّ الناس يقينًا أنهم بعيدون هم المخاطبون بأسمائهم.","th":[1],"p":null,"q":[39,53]},{"id":"mercy_encompasses_all","t":"أوسع من كل شيء آخر","b":"يقول الله إن عذابه يصيب من يشاء، ثم يقول في النَّفَس ذاته إن رحمته وسعت كل شيء. أحد الأمرين وُصف بلا حدّ، وليس هو الأول.","th":[1],"p":null,"q":[7,156]},{"id":"mercy_decreed_upon_himself","t":"كتبها على نفسه","b":"لم يُلزمه أحد. يذكر القرآن أنه كتب على نفسه الرحمة، ثم يبيّن ما يعنيه ذلك لمن عمل سوءًا بجهالة ثم تاب وأصلح.","th":[1],"p":null,"q":[6,54]},{"id":"mercy_wrong_then_seeks","t":"لم يكن الباب مغلقًا قط","b":"من يعمل سوءًا أو يظلم نفسه ثم يستغفر الله يجد الله غفورًا رحيمًا. الترتيب خطوتان، والثانية هي العمل الوحيد الذي عليك.","th":[1],"p":null,"q":[4,110]},{"id":"mercy_who_forgives_but_allah","t":"سؤال بجواب واحد","b":"للذين يذكرون الله بعد الذنب فيستغفرون يُطرح سؤال في وسط الآية: ومن يغفر الذنوب إلا الله؟ ليس هذا تسلية بلاغية. هو توجيه إلى الجهة الصحيحة.","th":[1],"p":null,"q":[3,135]},{"id":"mercy_sincere_repentance","t":"صادقة لا كاملة","b":"أُمر المؤمنون أن يتوبوا إلى الله توبة نصوحًا. الشرط الموضوع هو الصدق، لا ضمان ألّا تعود إليها أبدًا.","th":[1],"p":null,"q":[66,8]},{"id":"mercy_evil_replaced_with_good","t":"لا محوٌ بل تبديل","b":"لمن تاب وآمن وعمل صالحًا يقول القرآن إن الله يبدّل سيّئاتهم حسنات. لا يُمسح السجلّ فحسب، بل يُعاد كتابته لصالحك.","th":[1],"p":null,"q":[25,70]},{"id":"mercy_accepts_repentance","t":"هو الذي يقبل","b":"وهو الذي يقبل التوبة عن عباده ويعفو عن السيّئات، ويعلم ما تفعلون. ذُكر العلم والعفو معًا. لا شيء يحتاج أن يُخفى حتى يعمل هذا.","th":[1],"p":null,"q":[42,25]},{"id":"mercy_perpetual_forgiver","t":"أربعة شروط ووعد واحد","b":"أن يتوب، ويؤمن، ويعمل صالحًا، ثم يهتدي. والوعد المرفق أنه غفّار. لاحظ أن الاستمرار مذكور في القائمة، وأن المغفرة ليست مقنّنة بحسبه.","th":[1],"p":null,"q":[20,82]},{"id":"mercy_loves_the_repentant","t":"يحبّهم لأجل ذلك","b":"إن الله يحبّ التوّابين ويحبّ المتطهّرين. الرجوع ليس مجرد مقبول. هو الشيء المحبوب نفسه.","th":[1],"p":null,"q":[2,222]},{"id":"mercy_forgiver_of_sin","t":"اقرأ ترتيب الأسماء","b":"غافر الذنب، وقابل التوب، وشديد العقاب، وذي الطول. ثلاثة من هذه الأربعة موجّهة إليك. تعلّم الترتيب الذي يعرّف به نفسه.","th":[1],"p":null,"q":[40,3]},{"id":"mercy_call_upon_me","t":"ادعُ تُستجب لك","b":"يقول ربك ادعوني أستجب لكم. ثم تسمّي الآية الاستكبار، لا الذنب، سببًا يمنع الناس من السؤال. رفض السؤال يُعامل على أنه الأمر الخطير.","th":[1],"p":null,"q":[40,60]},{"id":"mercy_i_am_near","t":"لا واسطة في الجملة","b":"وإذا سألك عبادي عني، لا يقول: فقل لهم. يقول: فإني قريب. تُخطّى الرسول في التركيب اللغوي نفسه.","th":[1],"p":null,"q":[2,186]},{"id":"mercy_inform_my_servants","t":"أعلِنها","b":"يأمر الله رسوله أن يُنبّئ عباده أنه هو الغفور الرحيم. كان هذا شيئًا يُقال للناس، لا يُترك لهم ليستنتجوه بأنفسهم.","th":[1],"p":null,"q":[15,49]},{"id":"mercy_do_they_not_know","t":"ألم يعلموا؟","b":"تسأل الآية ألم يعلموا أن الله هو يقبل التوبة عن عباده ويأخذ الصدقات. تُقرأ كاستغراب أن يبقى أحد في شك من ذلك.","th":[1],"p":null,"q":[9,104]},{"id":"mercy_repent_soon_after","t":"قريبًا لا يومًا ما","b":"تُوصف التوبة التي يقبلها الله بأنها لمن يعمل السوء بجهالة ثم يتوب من قريب. الاستعجال في الآية لا في الشعور بالذنب.","th":[1],"p":null,"q":[4,17]},{"id":"mercy_merciful_and_loving","t":"رحيم وودود","b":"أمر شعيب قومه أن يستغفروا ويتوبوا، وختم باسمين معًا: رحيم ودود. أن تُغفر لك وأن تكون مرادًا ليسا شيئًا واحدًا، وكلاهما معروض.","th":[1],"p":null,"q":[11,90]},{"id":"mercy_forgiving_affectionate","t":"بعد الأخدود","b":"سورة تروي عن مؤمنين أُحرقوا أحياء لأجل إيمانهم تسمّيه الغفور الودود. هذا الموضع مقصود. اقرأ ما حوله.","th":[1],"p":null,"q":[85,14]},{"id":"mercy_do_you_not_like","t":"سؤال يستهدف الضغينة","b":"حين أُمروا أن يستمرّوا في العطاء لمن أساء إليهم إساءة بالغة، سُئل المؤمنون: ألا تحبّون أن يغفر الله لكم؟ هذا الاستدلال يُنهي الجدال في الحال.","th":[1],"p":null,"q":[24,22]},{"id":"mercy_satan_threatens_poverty","t":"صوتان يُميَّز بينهما","b":"أحدهما يَعِد بالفقر ويأمر بالفحشاء. والآخر يَعِد بمغفرة وفضل. تسمّي الآية أيّهما أيّ، لتعرف الصوت من الذي يعرضه.","th":[1],"p":null,"q":[2,268]},{"id":"mercy_repents_and_reforms","t":"تُب وأصلح","b":"بعد حكم شديد تنعطف الآية: فمن تاب من بعد ظلمه وأصلح فإن الله يتوب عليه. الإصلاح مذكور جزءًا من الرجوع، والرجوع ما زال مفتوحًا.","th":[1],"p":null,"q":[5,39]},{"id":"mercy_not_punished_while_seeking","t":"درعٌ من الاستغفار","b":"يقول الله إنه ما كان ليعذّبهم وهم يستغفرون. الاستغفار موصوف هنا حماية في الحاضر لا مجرد ترميم للماضي.","th":[1],"p":null,"q":[8,33]},{"id":"mercy_forgiveness_despite_wrongdoing","t":"رغم لا بسبب","b":"وإن ربك لذو مغفرة للناس على ظلمهم. الكلمة العاملة في الجملة هي على، أي رغم. لا ينتظر منك أن تستحقّ أولًا.","th":[1],"p":null,"q":[13,6]},{"id":"mercy_vast_in_forgiveness","t":"عرفك قبل أن تعرف نفسك","b":"تقول الآية إنه واسع المغفرة، ثم إنه أعلم بكم إذ أنشأكم من الأرض وإذ أنتم أجنّة. لا شيء فعلتَه حدّث معلوماته.","th":[1],"p":null,"q":[53,32]},{"id":"mercy_often_returning","t":"لمن يعود مرة بعد مرة","b":"ربكم أعلم بما في نفوسكم. إن تكونوا صالحين فإنه كان للأوّابين غفورًا. الكلمة تعني التكرار، وقد استُعملت في مقام المدح.","th":[1],"p":null,"q":[17,25]},{"id":"mercy_ever_merciful_to_believers","t":"هو وملائكته","b":"هو الذي يصلّي عليكم وملائكته ليخرجكم من الظلمات إلى النور. وكان بالمؤمنين رحيمًا. شيء يُفعل لأجلك وأنت تقرأ هذا.","th":[1],"p":null,"q":[33,43]},{"id":"mercy_pardon_and_ask_for_them","t":"بعد أن كلّفوه كل شيء","b":"في أعقاب معركة خُسرت بسبب المخالفة، قيل للنبي أن يعفو عنهم ويستغفر لهم ويشاورهم في الأمر. الثلاثة، بهذا الترتيب، للناس أنفسهم.","th":[1],"p":null,"q":[3,159]},{"id":"mercy_pardon_and_overlook","t":"ثلاثة أفعال قبل الأسماء","b":"أن تعفوا وتصفحوا وتغفروا، ثم فإن الله غفور رحيم. تأتي الأسماء تعليلًا، موضوعة في آخر الجملة كتوقيع.","th":[1],"p":null,"q":[64,14]},{"id":"mercy_he_pardons_much","t":"ويعفو عن كثير","b":"وما أصابكم من مصيبة فبما كسبت أيديكم ويعفو عن كثير. يُذكّر الناس بنصف هذه الجملة كثيرًا. والنصف الآخر هو الرحمة التي فيها.","th":[1],"p":null,"q":[42,30]},{"id":"mercy_would_leave_no_creature","t":"لما بقي أحد","b":"ولو يؤاخذ الله الناس بما كسبوا ما ترك على ظهرها من دابّة. أنت تقرأ هذا لأنه لا يفعل.","th":[1],"p":null,"q":[35,45]},{"id":"mercy_will_they_not_repent","t":"ما زال يسأل","b":"بعد وصف خطأ جسيم تسأل الآية: أفلا يتوبون إلى الله ويستغفرونه؟ الدعوة موجّهة إلى الذين صُوّبوا للتوّ بأعيانهم.","th":[1],"p":null,"q":[5,74]},{"id":"mercy_except_those_who_repent","t":"بند الاستثناء","b":"آية شديدة في كتمان الهدى تحمل استثناء: إلا الذين تابوا وأصلحوا وبيّنوا. كل تحذير في القرآن تقريبًا فيه باب مركّب.","th":[1],"p":null,"q":[2,160]},{"id":"mercy_hasten_to_forgiveness","t":"سارعوا إلى المغفرة","b":"الأمر أن تسارعوا إلى مغفرة من ربكم وجنّة عرضها السماوات والأرض. وُصفت المغفرة بأنها شيء يُسارَع إليه لا شيء يُنتظر.","th":[1],"p":null,"q":[3,133]},{"id":"mercy_race_toward","t":"تسابقوا لأجل هذا","b":"سابقوا إلى مغفرة من ربكم. من بين كل ما يمكن أن يتسابق فيه الناس، هذا هو الذي يحضّ عليه القرآن فعلًا. على ماذا تتسابق الآن؟","th":[1],"p":null,"q":[57,21]},{"id":"mercy_return_before","t":"قبل لا بعد","b":"وأنيبوا إلى ربكم وأسلموا له من قبل أن يأتيكم العذاب ثم لا تُنصرون. كلمة قبل هي الآية كلها. لا شيء ممنوع عنك إلا الوقت.","th":[1],"p":null,"q":[39,54]},{"id":"mercy_had_they_come_to_you","t":"كان يكفي أن يأتوا","b":"تقول الآية إنهم لو إذ ظلموا أنفسهم جاءوا فاستغفروا الله لوجدوا الله توّابًا رحيمًا. كانت العقبة في المجيء لا في القبول.","th":[1],"p":null,"q":[4,64]},{"id":"mercy_ever_accepting","t":"التوجيه الأخير","b":"قرب نهاية حياة النبي ومع مجيء الفتح، كان التوجيه أن يسبّح بحمد ربه ويستغفره، إنه كان توّابًا. حتى النصر ينتهي بالاستغفار.","th":[1],"p":null,"q":[110,3]},{"id":"mercy_ask_forgiveness_for_your_sin","t":"حتى خيرنا","b":"جاء الأمر بالاستغفار للذنب إلى الرسول نفسه، مقترنًا بالأمر بأن يعلم أنه لا إله إلا الله. لا أحد في هذا الدين فوق أن يسأل.","th":[1],"p":null,"q":[47,19]},{"id":"mercy_avoid_the_major","t":"عتبة واحدة تُحفظ","b":"اجتنبوا كبائر ما تُنهون عنه يكفّر الله عنكم سيّئاتكم ويدخلكم مدخلًا كريمًا. الخطّة معلنة: احفظ الحدّ حيث يكون أهمّ ما يكون.","th":[1],"p":null,"q":[4,31]},{"id":"mercy_accept_the_best","t":"يُحكم عليك بأفضل أيامك","b":"عن أولئك يقول الله إنه يتقبّل عنهم أحسن ما عملوا ويتجاوز عن سيّئاتهم. لا يُقرأ ملفّك عند أدنى نقطة فيه.","th":[1],"p":null,"q":[46,16]},{"id":"mercy_remove_their_misdeeds","t":"شُطبت كلها","b":"الذين آمنوا وعملوا الصالحات وُعدوا بتكفير سيّئاتهم وبجزاء أحسن الذي كانوا يعملون. نصفا هذه الآية كريمان.","th":[1],"p":null,"q":[29,7]},{"id":"mercy_allah_will_love_you","t":"اختبار الدعوى","b":"إن كنتم تحبّون الله فاتّبعوا الرسول يحببكم الله ويغفر لكم ذنوبكم. تُقاس المحبّة هنا بالاتّباع، وتُجزى بالمحبة والمغفرة معًا.","th":[1],"p":null,"q":[3,31]},{"id":"mercy_none_would_be_pure","t":"لم يزكّ أحد نفسه","b":"ولولا فضل الله عليكم ورحمته ما زكا منكم من أحد أبدًا. مهما كان الانضباط الذي تظنّ أنك بنيته، فالآية تنسب الفضل إلى جهة أخرى.","th":[1],"p":null,"q":[24,21]},{"id":"mercy_the_three_left_behind","t":"حتى ضاقت الأرض","b":"هُجر ثلاثة رجال حتى ضاقت عليهم الأرض بما رحبت وضاقت عليهم أنفسهم وعلموا أن لا ملجأ من الله إلا إليه. ثم تاب عليهم ليتوبوا.","th":[1],"p":null,"q":[9,118]},{"id":"mercy_angels_ask_for_you","t":"هناك من يدعو لك","b":"الذين يحملون العرش يستغفرون للذين آمنوا، يقولون إن رحمته وعلمه وسعا كل شيء، ويسألونه أن يغفر للذين تابوا. هناك ملائكة تدعو لك بالوصف.","th":[1],"p":null,"q":[40,7]},{"id":"mercy_affection_appointed","t":"محبّة وضعها هو","b":"إن الذين آمنوا وعملوا الصالحات سيجعل لهم الرحمن ودًّا. حتى المحبّة التي يحملها لك الناس موصوفة بأنها شيء يجعله هو.","th":[1],"p":null,"q":[19,96]},{"id":"mercy_would_have_hastened","t":"التأخير هو الرحمة","b":"وربك الغفور ذو الرحمة، لو يؤاخذهم بما كسبوا لعجّل لهم العذاب. الوقت الذي ما زال لديك هو تلك الآية وهي تعمل.","th":[1],"p":null,"q":[18,58]},{"id":"mercy_hundred_parts","t":"تسعة وتسعون ما زالت محبوسة","b":"قال النبي إن الله جعل الرحمة مئة جزء، فأنزل جزءًا واحدًا بين الخلق كلهم، وأمسك عنده تسعة وتسعين. كل لطف نلته يومًا خرج من ذلك الجزء الواحد.","th":[1],"p":null,"h":{"c":"صحيح مسلم","n":"2752","u":"https://sunnah.com/muslim:2752","g":"صحيح","by":null}},{"id":"mercy_prevails_over_wrath","t":"كُتب قبل كل شيء","b":"أخبر النبي أن الله لما قضى الخلق كتب في كتاب عنده أن رحمته تغلب غضبه. كُتب ذلك قبل أن يفعل أحد منا شيئًا في أي اتجاه.","th":[1],"p":null,"h":{"c":"صحيح البخاري","n":"3194","u":"https://sunnah.com/bukhari:3194","g":"صحيح","by":null}},{"id":"mercy_mother_and_child","t":"أرحم منها","b":"لما رأى النبي امرأة تبحث عن ولدها في لهفة ثم ضمّته، سأل أصحابه: أترون هذه طارحة ولدها في النار؟ قالوا: لا. قال: لله أرحم بعباده من هذه بولدها.","th":[1],"p":null,"h":{"c":"صحيح البخاري","n":"5999","u":"https://sunnah.com/bukhari:5999","g":"صحيح","by":null}},{"id":"mercy_lost_camel_joy","t":"أفرح ممّن وجدها","b":"وصف النبي رجلًا أضلّ راحلته في فلاة وعليها طعامه وشرابه، فأيس واضطجع ينتظر الموت، ثم وجدها قائمة عنده. الله، قال، أشدّ فرحًا بتوبتك من ذلك.","th":[1],"p":null,"h":{"c":"صحيح البخاري","n":"6308","u":"https://sunnah.com/bukhari:6308","g":"صحيح","by":null}},{"id":"mercy_a_people_who_sin","t":"خُلقت محتاجًا إلى هذا","b":"قال النبي إنكم لو لم تذنبوا لذهب الله بكم ولجاء بقوم يذنبون فيستغفرون فيغفر لهم. حاجتك إلى المغفرة ليست عيبًا في التصميم.","th":[1],"p":null,"h":{"c":"صحيح مسلم","n":"2749","u":"https://sunnah.com/muslim:2749","g":"صحيح","by":null}},{"id":"mercy_hand_by_night_and_day","t":"نوبتان والباب مفتوح دائمًا","b":"قال النبي إن الله يبسط يده بالليل ليتوب مسيء النهار، ويبسط يده بالنهار ليتوب مسيء الليل، حتى تطلع الشمس من مغربها. لا وقت إغلاق قبل ذلك.","th":[1],"p":null,"h":{"c":"صحيح مسلم","n":"2759","u":"https://sunnah.com/muslim:2759","g":"صحيح","by":null}},{"id":"mercy_as_my_servant_thinks","t":"أحسن الظنّ به","b":"في حديث قدسي أخبر النبي أن الله يقول: أنا عند ظنّ عبدي بي. ما تفترضه عن كيفية استقباله لك ليس شعورًا خاصًّا. هو يشكّل ما تناله.","th":[1],"p":null,"h":{"c":"صحيح مسلم","n":"2675","u":"https://sunnah.com/muslim:2675","g":"صحيح","by":null}},{"id":"mercy_forbidden_oppression","t":"حرّمه على نفسه","b":"في حديث قدسي طويل يعلن الله أنه حرّم الظلم على نفسه وجعله بين عباده محرّمًا، ثم يدعوهم أن يستهدوه ويستطعموه ويستغفروه. لم يأتك منه ظلم قط.","th":[1],"p":null,"h":{"c":"صحيح مسلم","n":"2577","u":"https://sunnah.com/muslim:2577","g":"صحيح","by":null}},{"id":"mercy_seventy_times_a_day","t":"المعصوم كان أكثرهم استغفارًا","b":"قال النبي إنه يستغفر الله ويتوب إليه في اليوم أكثر من سبعين مرة. لم يكن الاستغفار يومًا مقياسًا لمقدار ما فعله من سوء.","th":[1],"p":null,"h":{"c":"صحيح البخاري","n":"6307","u":"https://sunnah.com/bukhari:6307","g":"صحيح","by":null}},{"id":"mercy_hundred_times_a_day","t":"مئة مرة كل يوم","b":"كان النبي يأمر الناس بالتوبة إلى الله ويذكر أنه يتوب إليه في اليوم مئة مرة. جاء الأمر مقرونًا بعمله هو، لا مرتفعًا فوقه.","th":[1],"p":null,"h":{"c":"صحيح مسلم","n":"2702","u":"https://sunnah.com/muslim:2702","g":"صحيح","by":null}},{"id":"mercy_as_long_as_you_call","t":"ما دمت تدعو","b":"أخبر النبي في حديث قدسي أن العبد ما دام يدعو ربه ويرجوه غفر الله له ما كان منه ولا يبالي، ولو بلغت ذنوبه عنان السماء ثم استغفره لغفر له.","th":[1],"p":null,"h":{"c":"جامع الترمذي","n":"3540","u":"https://sunnah.com/tirmidhi:3540","g":"حسن","by":"دار السلام"}},{"id":"mercy_intention_recorded","t":"العمل الذي نويته","b":"أخبر النبي أن العبد إذا همّ بحسنة كُتبت له قبل أن يعملها، وإذا همّ بسيّئة فتركها من أجل الله كُتبت له أيضًا في صالحه.","th":[1],"p":null,"h":{"c":"صحيح البخاري","n":"7501","u":"https://sunnah.com/bukhari:7501","g":"صحيح","by":null}},{"id":"mercy_water_in_a_shoe","t":"ماء في خُفّ","b":"حكى النبي عن رجل اشتدّ عطشه فنزل بئرًا فشرب، ثم رأى كلبًا يلهث يأكل الثرى من العطش، فنزل فملأ خفّه ماء فسقاه، فشكر الله له فغفر له. وقال إن في كل كبد رطبة أجرًا.","th":[1,5],"p":null,"h":{"c":"صحيح البخاري","n":"6009","u":"https://sunnah.com/bukhari:6009","g":"صحيح","by":null}},{"id":"mercy_if_either_truly_knew","t":"لو علم كلٌّ منهما","b":"أخبر النبي أن المؤمن لو علم ما عند الله من العقوبة ما طمع بجنته أحد، ولو علم الكافر ما عند الله من الرحمة ما قنط من جنته أحد. الرجاء والخوف كلاهما ينبغي أن يبقى يقظًا.","th":[1,6],"p":null,"h":{"c":"صحيح مسلم","n":"2755","u":"https://sunnah.com/muslim:2755","g":"صحيح","by":null}},{"id":"mercy_near_to_those_who_do_good","t":"الرحمة قريبة","b":"تأمر الآية بدعاء الله بين الخشية والرجاء، ثم تخبر أن رحمته دانية ممن يُحسن. ليست بعيدة، ولا مؤجلة. قريبة.","th":[1,4],"p":null,"q":[7,56]},{"id":"mercy_look_at_the_traces","t":"تأمّل الأثر","b":"تدعوك الآية إلى تأمّل أثر رحمة الله في إحياء الأرض بعد أن كانت هامدة، وتخبر أن الذي يفعل ذلك يحيي الموتى. ما بدا منتهيًا كان ينتظر.","th":[1,2],"p":null,"q":[30,50]},{"id":"mercy_your_hardship_weighed_on_him","t":"يشقّ عليه ما يشقّ عليك","b":"تصف الآية الرسول بأنه منكم، يشقّ عليه ما يشقّ عليكم، شديد الحرص عليكم، رؤوف رحيم بالمؤمنين. هكذا يصف الوحي من جاء به.","th":[1],"p":null,"q":[9,128]},{"id":"patience_with_hardship_ease","t":"معه لا بعده","b":"لا تقول الآية إن اليسر يأتي بعد العسر. تقول إن مع العسر يسرًا، ثم تكرّر الجملة. الفرج لا ينتظر خلف الشدّة. هو داخلها.","th":[2],"p":null,"q":[94,5]},{"id":"patience_a_way_out","t":"مخرج لم تره بعد","b":"ومن يتّق الله يجعل له مخرجًا. لا تصف الآية المخرج ولا تقول متى يظهر. تسمّي الشرط المرتبط به فقط.","th":[2],"p":null,"q":[65,2]},{"id":"patience_he_is_sufficient","t":"كافٍ كلمة قويّة","b":"ومن يتوكّل على الله فهو حسبه. ليس معينًا ولا مساندًا. كافيًا. لا شيء آخر في هذا الترتيب يحتاج إلى إكمال.","th":[2],"p":null,"q":[65,3]},{"id":"patience_hasbunallah","t":"ما قالوه حين قيل لهم خافوا","b":"جاءهم من يخوّفهم بحجم الجيش المجتمع عليهم فزادهم ذلك إيمانًا. الذي قالوه: حسبنا الله ونعم الوكيل.","th":[2],"p":null,"q":[3,173]},{"id":"patience_allah_is_with_the_patient","t":"معيّة لا مجرد أجر","b":"استعينوا بالصبر والصلاة، إن الله مع الصابرين. الأجر المذكور هنا للصبر هو معيّته، مبذولة والشدّة ما زالت جارية.","th":[2],"p":null,"q":[2,153]},{"id":"patience_we_will_test_you","t":"أُعلن مسبقًا","b":"خوف وجوع ونقص من الأموال والأنفس والثمرات. نُشرت القائمة مقدّمًا، وتلاها بشرى للصابرين. لا شيء منها يأتي دون إعلان.","th":[2],"p":null,"q":[2,155]},{"id":"patience_inna_lillah","t":"جملتان في عبارة واحدة","b":"إنا لله وإنا إليه راجعون. الكلمات التي تُقال عند القبر هي أولًا إعلان ملكيّة. الحزن أهون حملًا حين تعرف لمن كان.","th":[2],"p":null,"q":[2,156]},{"id":"patience_within_its_capacity","t":"قُدّر على مقاسك","b":"لا يكلّف الله نفسًا إلا وسعها. ليس هذا وعدًا بأن يبدو محتملًا. هو بيان عمّن أخذ المقاس.","th":[2],"p":null,"q":[2,286]},{"id":"patience_reward_without_account","t":"الأجر الوحيد بلا عدّ","b":"إنما يوفّى الصابرون أجرهم بغير حساب. كل عمل آخر في القرآن له مضاعفة معلومة. هذا تُرك مفتوحًا عن قصد.","th":[2],"p":null,"q":[39,10]},{"id":"patience_and_allah_is_with","t":"أطيعوا ولا تنازعوا واصبروا","b":"قبل معركة كان التوجيه أن يطيعوا وألّا يتنازعوا فتذهب ريحهم وأن يصبروا. سُمّي النزاع الداخلي هو الذي يُذهب قوّتك، لا العدوّ.","th":[2],"p":null,"q":[8,46]},{"id":"patience_persevere_and_endure","t":"اثبتوا أطول منهم","b":"اصبروا وصابروا ورابطوا واتّقوا الله. أربعة أوامر، ثلاثة منها عن البقاء حيث وُضعت.","th":[2],"p":null,"q":[3,200]},{"id":"patience_only_through_allah","t":"حتى الصبر يُعطى","b":"واصبر وما صبرك إلا بالله. إن كنت قد ثبتّ فتلك القدرة أُمدّت بها. اسألها أكثر كما تسأل أي شيء آخر.","th":[2],"p":null,"q":[16,127]},{"id":"patience_be_and_it_is","t":"كلمة واحدة","b":"إنما أمره إذا أراد شيئًا أن يقول له كن فيكون. الذي تسأله منذ زمن يبعد كلمة واحدة من جهته سبحانه.","th":[2],"p":null,"q":[36,82]},{"id":"patience_written_before","t":"في السجلّ سلفًا","b":"ما أصاب من مصيبة في الأرض ولا في أنفسكم إلا في كتاب من قبل أن نبرأها. أسوأ أيامك كان له ملفّ قبل أن يكون للعالم ملفّ.","th":[2],"p":null,"q":[57,22]},{"id":"patience_he_guides_the_heart","t":"الذي يُهدى هو القلب","b":"ما أصاب من مصيبة إلا بإذن الله، ومن يؤمن بالله يهدِ قلبه. الوعد المرفق بالمصيبة ليس رفعها. هو قلب مهديّ ما دامت.","th":[2],"p":null,"q":[64,11]},{"id":"patience_do_not_weaken","t":"قيل بعد هزيمة","b":"ولا تهنوا ولا تحزنوا وأنتم الأعلون إن كنتم مؤمنين. قيل هذا لقوم خسروا للتوّ لا لقوم انتصروا للتوّ.","th":[2],"p":null,"q":[3,139]},{"id":"patience_when_is_the_help","t":"حتى الرسول سأل","b":"تصف الآية شدّة بلغت بالرسول ومن معه أن يقولوا: متى نصر الله؟ يسجّل القرآن السؤال ثم يجيب أن نصره قريب.","th":[2],"p":null,"q":[2,214]},{"id":"patience_until_it_is_evident","t":"الابتلاء يُظهر لا يُخبر","b":"ولنبلونّكم حتى نعلم المجاهدين منكم والصابرين. هو يعلم سلفًا. الابتلاء هو الذي يجعل ذلك ظاهرًا، ولك أنت أيضًا.","th":[2],"p":null,"q":[47,31]},{"id":"patience_do_people_think","t":"القول وحده لا يكفي","b":"أحسب الناس أن يُتركوا أن يقولوا آمنّا وهم لا يُفتنون؟ الدعوى مقبولة، والآية تعلن فقط أنها ستُفحص.","th":[2],"p":null,"q":[29,2]},{"id":"patience_those_who_strive","t":"تحرّك يُدلّك","b":"والذين جاهدوا فينا لنهدينّهم سبلنا. الهداية موعودة لمن هم في الطريق فعلًا. الاتجاه يأتي بعد الحركة لا قبلها.","th":[2],"p":null,"q":[29,69]},{"id":"patience_reward_not_lost","t":"لا شيء يبقى خارج السجلّ","b":"واصبر فإن الله لا يضيع أجر المحسنين. كل ما فعلته ولم ينتبه له أحد مودَع حيث لا يضيع شيء.","th":[2],"p":null,"q":[11,115]},{"id":"patience_peace_for_what_you_endured","t":"السلام عند الباب","b":"تستقبلهم الملائكة بالسلام بما صبروا. أول كلمات تُقال لهم تشير إلى أشقّ جزء في حياتهم.","th":[2],"p":null,"q":[13,24]},{"id":"patience_the_chamber","t":"غرفة اشتُريت بالصبر","b":"أولئك يُجزون الغرفة بما صبروا ويُلقّون فيها تحيّة وسلامًا. كان الصبر هو الثمن، وقد دُفع بالفعل.","th":[2],"p":null,"q":[25,75]},{"id":"patience_garden_and_silk","t":"جزاء من جنّة وحرير","b":"وجزاهم بما صبروا جنّة وحريرًا. تسمّي الآية الراحة المعيّنة الممنوحة مقابل المشقّة المعيّنة المحمولة.","th":[2],"p":null,"q":[76,12]},{"id":"patience_advised_each_other","t":"أربعة وآخرها لغيرك","b":"والعصر إن الإنسان لفي خسر، إلا الذين آمنوا وعملوا الصالحات وتواصوا بالحقّ وتواصوا بالصبر. البند الأخير صبر تعطيه للآخرين.","th":[2],"p":null,"q":[103,3]},{"id":"patience_rely_upon_allah","t":"توكّل وليكفِ ذلك","b":"وتوكّل على الله وكفى بالله وكيلًا. وُضع الأمر وتعليله في آية قصيرة واحدة حتى لا يؤخذ أحدهما وحده.","th":[2],"p":null,"q":[33,3]},{"id":"patience_worship_and_rely","t":"اعبده واستند إليه","b":"ولله غيب السماوات والأرض وإليه يُرجع الأمر كله فاعبده وتوكّل عليه. قُدّم التوكّل نتيجة طبيعية لمعرفة من يملك الغيب.","th":[2],"p":null,"q":[11,123]},{"id":"patience_why_should_we_not","t":"ولمَ لا نتوكّل؟","b":"أجاب الرسل على الأذى بسؤال: وما لنا ألّا نتوكّل على الله وقد هدانا سبلنا؟ عوملت الهداية الماضية دليلًا على الثقة الحاضرة.","th":[2],"p":null,"q":[14,12]},{"id":"patience_if_allah_aids_you","t":"الحساب الوحيد المهمّ","b":"إن ينصركم الله فلا غالب لكم، وإن يخذلكم فمن ذا الذي ينصركم من بعده؟ ثم قيل: وعلى الله فليتوكّل المؤمنون. استُخرجت النتيجة نيابة عنك.","th":[2],"p":null,"q":[3,160]},{"id":"patience_do_not_grieve","t":"رجلان في غار","b":"مطاردًا مختبئًا والباحثون على الباب، قال لصاحبه لا تحزن إن الله معنا. ثم أُنزلت السكينة. جاءت الطمأنينة قبل النجاة.","th":[2],"p":null,"q":[9,40]},{"id":"patience_is_not_allah_sufficient","t":"سؤال تُرك مفتوحًا","b":"أليس الله بكافٍ عبده؟ يطرحه القرآن ويمضي دون جدال. بعض الأسئلة يجيب عنها مقدار الحرج في الإجابة عنها بصدق.","th":[2],"p":null,"q":[39,36]},{"id":"patience_no_remover_except_him","t":"عنوان واحد للأمرين","b":"وإن يمسسك الله بضرّ فلا كاشف له إلا هو، وإن يمسسك بخير فهو على كل شيء قدير. اليد نفسها مذكورة في نصفَي الآية.","th":[2],"p":null,"q":[6,17]},{"id":"patience_do_not_fear_do_not_grieve","t":"قيل مرتين في الاتجاهين","b":"الذين قالوا ربنا الله ثم استقاموا تتنزّل عليهم الملائكة ألّا تخافوا ولا تحزنوا. عبارة تنظر إلى الأمام وأخرى إلى الوراء. كلاهما مغطّى.","th":[2],"p":null,"q":[41,30]},{"id":"patience_perhaps_you_hate","t":"ربما تقرؤه بالمقلوب","b":"وعسى أن تكرهوا شيئًا وهو خير لكم، وعسى أن تحبّوا شيئًا وهو شرّ لكم. والله يعلم وأنتم لا تعلمون. لا شيء في الآية يطلب منك أن يعجبك.","th":[2],"p":null,"q":[2,216]},{"id":"patience_he_has_not_forsaken_you","t":"الصمت لم يكن هجرًا","b":"حين توقّف الوحي وقال الناس إنه قد وُدّع، جاء الجواب: ما ودّعك ربك وما قلى. الفترة الصامتة ليست حكمًا.","th":[2],"p":null,"q":[93,3]},{"id":"patience_wondrous_affair","t":"كلا الطريقين رابح","b":"قال النبي: عجبًا لأمر المؤمن، إن أمره كله خير، وليس ذاك لأحد إلا للمؤمن: إن أصابته سرّاء شكر فكان خيرًا له، وإن أصابته ضرّاء صبر فكان خيرًا له.","th":[2],"p":null,"h":{"c":"صحيح مسلم","n":"2999","u":"https://sunnah.com/muslim:2999","g":"صحيح","by":null}},{"id":"patience_even_a_thorn","t":"حتى الشوكة","b":"قال النبي: ما يصيب المسلم من نصب ولا وصب ولا همّ ولا حزن ولا أذى ولا غمّ، حتى الشوكة يُشاكها، إلا كفّر الله بها من خطاياه. القائمة تنزل إلى أصغر شيء.","th":[2],"p":null,"h":{"c":"صحيح البخاري","n":"5641","u":"https://sunnah.com/bukhari:5641","g":"صحيح","by":null}},{"id":"patience_whom_he_wishes_good","t":"علامة غير مرحّب بها","b":"قال النبي: من يرد الله به خيرًا يُصب منه. هذا يعيد صياغة السؤال الذي تطرحه على الأرجح عن حالك.","th":[2],"p":null,"h":{"c":"صحيح البخاري","n":"5645","u":"https://sunnah.com/bukhari:5645","g":"صحيح","by":null}},{"id":"patience_greatest_trial","t":"على قدر الأجر","b":"قال النبي: إن عظم الجزاء مع عظم البلاء، وإن الله إذا أحبّ قومًا ابتلاهم، فمن رضي فله الرضا ومن سخط فله السخط.","th":[2],"p":null,"h":{"c":"جامع الترمذي","n":"2396","u":"https://sunnah.com/tirmidhi:2396","g":"حسن","by":"دار السلام"}},{"id":"patience_at_the_first_strike","t":"الساعة الأولى هي المعتبرة","b":"مرّ النبي بامرأة تبكي عند قبر فقال لها: اتّقي الله واصبري. لم تعرفه فأجابت بحدّة. فلما علمت من هو جاءت تعتذر، فقال: إنما الصبر عند الصدمة الأولى.","th":[2],"p":null,"h":{"c":"صحيح البخاري","n":"1283","u":"https://sunnah.com/bukhari:1283","g":"صحيح","by":null}},{"id":"patience_what_passed_you_by","t":"لم يكن مصوّبًا نحوك أصلًا","b":"علّم النبي صحابيًّا شابًّا أن يعلم أن ما أخطأه لم يكن ليصيبه، وأن ما أصابه لم يكن ليخطئه. جملتان تفكّكان أكثر الندم.","th":[2],"p":null,"h":{"c":"جامع الترمذي","n":"2516","u":"https://sunnah.com/tirmidhi:2516","g":"حسن","by":"دار السلام"}},{"id":"patience_strength_in_anger","t":"تعريف آخر للقوّة","b":"قال النبي: ليس الشديد بالصُّرَعة، إنما الشديد الذي يملك نفسه عند الغضب. نُقل المقياس من الذراعين إلى الطبع.","th":[2],"p":null,"h":{"c":"صحيح البخاري","n":"6114","u":"https://sunnah.com/bukhari:6114","g":"صحيح","by":null}},{"id":"patience_do_not_say_if_only","t":"لا تفتح ذلك الباب","b":"قال النبي: احرص على ما ينفعك واستعن بالله ولا تعجز، وإن أصابك شيء فلا تقل لو أني فعلت كذا، ولكن قل: قدّر الله وما شاء فعل، فإن لو تفتح عمل الشيطان.","th":[2],"p":null,"h":{"c":"صحيح مسلم","n":"2664","u":"https://sunnah.com/muslim:2664","g":"صحيح","by":null}},{"id":"patience_no_better_gift","t":"أفضل ما أُعطيه أحد","b":"قال النبي: من يتصبّر يصبّره الله، وما أُعطي أحد عطاءً خيرًا وأوسع من الصبر. وهو متاح بالطلب.","th":[2],"p":null,"h":{"c":"صحيح البخاري","n":"1469","u":"https://sunnah.com/bukhari:1469","g":"صحيح","by":null}},{"id":"patience_when_i_take_his_beloved","t":"جزاء واحد لا غير","b":"في حديث قدسي أخبر النبي أن الله يقول: ما لعبدي المؤمن عندي جزاء إذا قبضتُ صفيّه من أهل الدنيا ثم احتسبه إلا الجنة.","th":[2],"p":null,"h":{"c":"صحيح البخاري","n":"6424","u":"https://sunnah.com/bukhari:6424","g":"صحيح","by":null}},{"id":"patience_out_hungry_home_full","t":"تخرج جائعة وتعود شبعى","b":"أخبر النبي أنكم لو توكلتم على الله حقّ توكّله لرزقكم كما يرزق الطير، تخرج في الصباح جائعة وتعود في المساء شبعى. والطير مع ذلك تغادر أعشاشها.","th":[2],"p":null,"h":{"c":"جامع الترمذي","n":"2344","u":"https://sunnah.com/tirmidhi:2344","g":"حسن","by":"دار السلام"}},{"id":"patience_turned_away_at_the_door","t":"تُغلق دونه الأبواب","b":"أخبر النبي أنه رُبّ أشعث تُردّ عنه أبواب الناس، لو أقسم على الله لأبرّه. الأبواب المغلقة بين الناس لا تقول الكثير عن المنزلة عند الله.","th":[2,5],"p":null,"h":{"c":"صحيح مسلم","n":"2622","u":"https://sunnah.com/muslim:2622","g":"صحيح","by":null}},{"id":"patience_she_could_not_imagine_better","t":"لم تتخيّل خيرًا منه","b":"علّم النبي أن من أصابته مصيبة فاسترجع، ثم سأل الله أن يأجره فيها وأن يخلف له خيرًا منها، أخلف الله له خيرًا منها. قالتها أم سلمة حين مات أبو سلمة وهي لا تتصوّر أحدًا خيرًا منه، فأبدلها الله رسوله.","th":[2,4],"p":null,"h":{"c":"صحيح مسلم","n":"918a","u":"https://sunnah.com/muslim:918a","g":"صحيح","by":null}},{"id":"patience_in_his_sight","t":"تحت الرعاية","b":"أمر الله نبيه أن يصبر لقضاء ربه لأنه تحت رعايته وعينه، وأن يسبّح بحمده حين يقوم. لم يكن الصبر المطلوب منه صبرًا في وحدة.","th":[2],"p":null,"q":[52,48]},{"id":"patience_when_the_chest_feels_tight","t":"حين يضيق الصدر","b":"أخبر الله نبيه أنه يعلم ما يجده في صدره من ضيق بسبب أقوالهم، ثم جاء الجواب في الآيات التالية: التسبيح والحمد والسجود. الضيق اعتُرف به قبل أن يُطلب منه شيء.","th":[2],"p":null,"q":[15,97]},{"id":"worship_dawn_witnessed","t":"أحدٌ يشهد تلك بالذات","b":"أقم الصلاة لدلوك الشمس إلى غسق الليل وقرآن الفجر، إن قرآن الفجر كان مشهودًا. أصعب صلاة تُدرك هي التي لها شهود.","th":[3],"p":null,"q":[17,78]},{"id":"worship_prayer_restrains","t":"إن لم تكن تغيّرك","b":"إن الصلاة تنهى عن الفحشاء والمنكر، ولذكر الله أكبر. تُسند الآية إلى الصلاة أثرًا خارج السجّادة. ابحث عن ذلك الأثر.","th":[3],"p":null,"q":[29,45]},{"id":"worship_seek_help","t":"أداتان في آية واحدة","b":"استعينوا بالصبر والصلاة، وإنها لكبيرة إلا على الخاشعين. يعترف القرآن بثقلها في الجملة نفسها التي يوصي بها فيها.","th":[3],"p":null,"q":[2,45]},{"id":"worship_humbly_submissive","t":"أول صفة ذُكرت","b":"قد أفلح المؤمنون، وأول صفة تُذكر الخشوع في صلاتهم. لا طولها. حال القلب داخلها.","th":[3],"p":null,"q":[23,2]},{"id":"worship_heedless_of_prayer","t":"ساهون لا تاركون","b":"التحذير ليس لمن ترك الصلاة بل لمن هو عنها ساهٍ. الصلاة ما زالت تُؤدّى. وهذا بالضبط ما يجعل الآية مقلقة.","th":[3],"p":null,"q":[107,5]},{"id":"worship_specified_times","t":"جدولٌ لا مزاج","b":"إن الصلاة كانت على المؤمنين كتابًا موقوتًا. لم تُترك للحظة التي تشعر فيها بالاستعداد. الأوقات الثابتة هي الرحمة فيها.","th":[3],"p":null,"q":[4,103]},{"id":"worship_leave_the_trade","t":"وذروا البيع","b":"إذا نودي للصلاة من يوم الجمعة فاسعوا إلى ذكر الله وذروا البيع. ثم تقول الآية: ذلكم خير لكم إن كنتم تعلمون.","th":[3],"p":null,"q":[62,9]},{"id":"worship_sides_part_from_beds","t":"جنوبهم تفارق المضاجع","b":"تتجافى جنوبهم عن المضاجع يدعون ربهم خوفًا وطمعًا ومما رزقناهم ينفقون. تصف الآية اللحظة نفسها التي يُرفع فيها الغطاء.","th":[3],"p":null,"q":[32,16]},{"id":"worship_measured_recitation","t":"ببطء وعن قصد","b":"ورتّل القرآن ترتيلًا. التوجيه عن الإيقاع. لم يُطلب من أحد قط أن يُنهيه بسرعة.","th":[3],"p":null,"q":[73,4]},{"id":"worship_made_easy_for_remembrance","t":"يُسّر وقيلت أربع مرات","b":"ولقد يسّرنا القرآن للذكر فهل من مدّكر؟ تتكرّر الآية أربع مرات في السورة نفسها كأن العرض يحتاج إلحاحًا.","th":[3],"p":null,"q":[54,17]},{"id":"worship_healing_and_mercy","t":"أُنزل دواءً","b":"وننزّل من القرآن ما هو شفاء ورحمة للمؤمنين. وُصف دواءً قبل أن يُوصف أدبًا.","th":[3],"p":null,"q":[17,82]},{"id":"worship_healing_in_the_breasts","t":"لما في الصدر","b":"قد جاءتكم موعظة من ربكم وشفاء لما في الصدور وهدى ورحمة. ذُكر الصدر تحديدًا. وترتيب الأربعة كذلك.","th":[3],"p":null,"q":[10,57]},{"id":"worship_mountain_humbled","t":"جبل كان سيتصدّع","b":"لو أنزلنا هذا القرآن على جبل لرأيته خاشعًا متصدّعًا من خشية الله. وتلك الأمثال تُضرب للناس لعلهم يتفكّرون.","th":[3],"p":null,"q":[59,21]},{"id":"worship_locks_upon_hearts","t":"أم على قلوب أقفالها","b":"أفلا يتدبّرون القرآن أم على قلوب أقفالها؟ لا يسمح السؤال إلا بتفسيرين، وليس فيهما ما يُمدح.","th":[3],"p":null,"q":[47,24]},{"id":"worship_reflect_upon_its_verses","t":"أُنزل ليُتدبّر","b":"كتاب أنزلناه إليك مبارك ليدّبّروا آياته وليتذكّر أولو الألباب. التدبّر مذكور غايةً لا إضافةً اختيارية.","th":[3],"p":null,"q":[38,29]},{"id":"worship_we_will_guard_it","t":"محفوظ لا مجرد مصون","b":"إنا نحن نزّلنا الذكر وإنا له لحافظون. بعد أربعة عشر قرنًا تحمل النصّ نفسه في هاتف. كان الادّعاء قابلًا للفحص، وقد فُحص.","th":[3],"p":null,"q":[15,9]},{"id":"worship_you_we_worship","t":"التحوّل في وسط السورة","b":"تُثني سورة الفاتحة عليه بضمير الغائب ثم تلتفت فتخاطبه مباشرة: إياك نعبد وإياك نستعين. سبع عشرة مرة في اليوم تتوقّف عن الحديث عنه وتبدأ الحديث معه.","th":[3],"p":null,"q":[1,5]},{"id":"worship_listen_and_be_silent","t":"استمعوا وأنصتوا","b":"وإذا قُرئ القرآن فاستمعوا له وأنصتوا لعلكم تُرحمون. عُلّقت الرحمة بالإنصات، وهو النصف الأصعب.","th":[3],"p":null,"q":[7,204]},{"id":"worship_skins_shiver","t":"الجلد أولًا ثم القلب","b":"تقشعرّ منه جلود الذين يخشون ربهم، ثم تلين جلودهم وقلوبهم إلى ذكر الله. تتتبّع الآية ردّ فعل جسديًّا يستقرّ حالًا روحية.","th":[3],"p":null,"q":[39,23]},{"id":"worship_created_to_worship","t":"الغاية المعلنة","b":"وما خلقت الجنّ والإنس إلا ليعبدون. كل ما عدا ذلك في أسبوعك يقع أسفل جملة بهذا القِصر.","th":[3],"p":null,"q":[51,56]},{"id":"worship_sincere_to_him","t":"كان الأمر بالإخلاص","b":"وما أُمروا إلا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاة ويؤتوا الزكاة. الإخلاص مذكور أمرًا لا شعورًا يأتي وحده.","th":[3],"p":null,"q":[98,5]},{"id":"worship_prostrate_and_draw_near","t":"اقترب أكثر","b":"واسجد واقترب. تنتهي آخر آية من أول سورة نزلت بتوجيه عن الأرض ووعدٍ عن المسافة.","th":[3],"p":null,"q":[96,19]},{"id":"worship_blessed_night","t":"أُنزل في ليلة مباركة","b":"إنا أنزلناه في ليلة مباركة إنا كنا منذرين. من كل الليالي التي كانت، اختيرت واحدة لتحمله.","th":[3],"p":null,"q":[44,3]},{"id":"worship_better_than_a_thousand","t":"أثمن من عمر كامل","b":"ليلة القدر خير من ألف شهر. ثلاثة وثمانون عامًا من العبادة، تُعرض في ليلة واحدة، على أناس قد لا يبلغون ثلاثة وثمانين عامًا.","th":[3],"p":null,"q":[97,3]},{"id":"worship_bow_and_prostrate","t":"أربعة أفعال بلا أوصاف","b":"اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون. تعطي الآية أشياء تُفعل لا حالًا يُبلَغ.","th":[3],"p":null,"q":[22,77]},{"id":"worship_learn_and_teach","t":"النصفان مذكوران","b":"قال النبي: خيركم من تعلّم القرآن وعلّمه. لم تُعطَ المرتبة لمن اكتفى بالتعلّم.","th":[3],"p":null,"h":{"c":"صحيح البخاري","n":"5027","u":"https://sunnah.com/bukhari:5027","g":"صحيح","by":null}},{"id":"worship_quran_intercedes","t":"سيتكلّم عنك","b":"قال النبي: اقرؤوا القرآن فإنه يأتي يوم القيامة شفيعًا لأصحابه. وُصفت العلاقة صحبةً، والصحبة تحتاج وقتًا.","th":[3],"p":null,"h":{"c":"صحيح مسلم","n":"804","u":"https://sunnah.com/muslim:804","g":"صحيح","by":null}},{"id":"worship_a_letter_is_ten","t":"يُحسب بالحرف","b":"قال النبي: من قرأ حرفًا من كتاب الله فله به حسنة، والحسنة بعشر أمثالها، وزاد أن ألم ليس حرفًا بل ثلاثة أحرف.","th":[3],"p":null,"h":{"c":"جامع الترمذي","n":"2910","u":"https://sunnah.com/tirmidhi:2910","g":"حسن","by":"دار السلام"}},{"id":"worship_prayer_on_time","t":"سُئل عن أحبّ الأعمال","b":"لما سُئل أيّ العمل أحبّ إلى الله، قال النبي: الصلاة على وقتها. ثم برّ الوالدين، ثم الجهاد في سبيل الله. هذا هو الترتيب الذي أُعطي.","th":[3],"p":null,"h":{"c":"صحيح البخاري","n":"527","u":"https://sunnah.com/bukhari:527","g":"صحيح","by":null}},{"id":"worship_river_at_the_door","t":"خمس مرات في النهر","b":"سأل النبي: هل يبقى من درنه شيء لو اغتسل رجل في نهر بباب داره خمس مرات في اليوم؟ قالوا: لا. قال: فذلك مثل الصلوات الخمس.","th":[3],"p":null,"h":{"c":"صحيح البخاري","n":"528","u":"https://sunnah.com/bukhari:528","g":"صحيح","by":null}},{"id":"worship_expiation_between_them","t":"تُكفَّر من واحدة إلى التي تليها","b":"قال النبي: الصلوات الخمس والجمعة إلى الجمعة ورمضان إلى رمضان مكفّرات ما بينهنّ ما اجتُنبت الكبائر.","th":[3],"p":null,"h":{"c":"صحيح مسلم","n":"233","u":"https://sunnah.com/muslim:233","g":"صحيح","by":null}},{"id":"worship_closest_in_prostration","t":"أقرب نقطة","b":"قال النبي: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء. أقرب لحظة هي أيضًا التي يكون فيها وجهك على الأرض.","th":[3],"p":null,"h":{"c":"صحيح مسلم","n":"482","u":"https://sunnah.com/muslim:482","g":"صحيح","by":null}},{"id":"worship_last_third_of_night","t":"كل ليلة العرض نفسه","b":"قال النبي إن الله ينزل في الثلث الأخير من كل ليلة نزولًا يليق به فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له.","th":[3],"p":null,"h":{"c":"صحيح البخاري","n":"1145","u":"https://sunnah.com/bukhari:1145","g":"صحيح","by":null}},{"id":"worship_best_after_obligatory","t":"أفضل النافلة","b":"قال النبي: أفضل الصيام بعد رمضان شهر الله المحرّم، وأفضل الصلاة بعد الفريضة صلاة الليل. كلا الجوابين يبتعد عن ضوء النهار وعن الناس.","th":[3],"p":null,"h":{"c":"صحيح مسلم","n":"1163","u":"https://sunnah.com/muslim:1163","g":"صحيح","by":null}},{"id":"worship_most_consistent","t":"قليل وكل يوم","b":"قال النبي: أحبّ الأعمال إلى الله أدومها وإن قلّ. ولما سُئلت عائشة عن عمله قالت: كان إذا عمل عملًا أثبته.","th":[3],"p":null,"h":{"c":"صحيح البخاري","n":"6464","u":"https://sunnah.com/bukhari:6464","g":"صحيح","by":null}},{"id":"worship_nearer_step_by_step","t":"قربًا بعد قرب","b":"روى النبي عن الله أن عبده لا يتقرّب إليه بشيء أحبّ إليه مما افترضه عليه، ولا يزال يتقرّب إليه بالنوافل حتى يحبه، فإن سأله أعطاه، وإن استعاذ به أعاذه.","th":[3],"p":null,"h":{"c":"صحيح البخاري","n":"6502","u":"https://sunnah.com/bukhari:6502","g":"صحيح","by":null}},{"id":"worship_aim_close_and_keep_going","t":"قارِب وواصِل","b":"أخبر النبي أن الدين يسر، ولن يُشادّه أحد إلا غلبه، فأوصى بالسداد والمقاربة والبشرى، والاستعانة بأول النهار وآخره وشيء من الليل.","th":[3],"p":null,"h":{"c":"صحيح البخاري","n":"39","u":"https://sunnah.com/bukhari:39","g":"صحيح","by":null}},{"id":"worship_two_rewards_for_the_struggle","t":"أجران على المشقة","b":"أخبر النبي أن الماهر بالقرآن مع السفرة الكرام البررة، وأن الذي يقرؤه ويتتعتع فيه وهو عليه شاقّ له أجران. الصعوبة ليست علامة على التوقف.","th":[3],"p":null,"h":{"c":"صحيح مسلم","n":"798a","u":"https://sunnah.com/muslim:798a","g":"صحيح","by":null}},{"id":"worship_recite_what_is_easy","t":"ما يسهل عليك","b":"علم الله أن من الناس مرضى ومسافرين ومجاهدين، فأمر في الآية نفسها مرتين بقراءة ما يسهل من القرآن، وأخبر أن ما يقدّمه المرء من خير يجده عند الله أفضل وأعظم ثوابًا.","th":[3],"p":null,"q":[73,20]},{"id":"worship_has_the_time_not_come","t":"أما حان الوقت؟","b":"تسأل الآية المؤمنين: أما حان أن تلين قلوبهم وتخضع عند ذكر الله؟ والآية التي تليها تذكر إحياء الأرض بعد موتها. السؤال يتبعه رجاء.","th":[3],"p":null,"q":[57,16]},{"id":"worship_a_trade_that_will_not_fail","t":"تجارة لا تخسر","b":"يصف القرآن من يقرؤون كتاب الله ويقيمون الصلاة وينفقون في السر والعلن بأنهم يرجون تجارة لا تخسر أبدًا. والتلاوة أول ما ذُكر.","th":[3],"p":null,"q":[35,29]},{"id":"worship_constant_in_their_prayer","t":"المداومون على صلاتهم","b":"تصف السورة الإنسان بأنه خُلق قلقًا، يجزع إذا أصابه الشر ويمسك إذا أصابه الخير. ثم تذكر من يُستثنى: المصلّين الذين يداومون على صلاتهم.","th":[3,2],"p":null,"q":[70,23]},{"id":"worship_then_turn_to_your_lord","t":"وجهة الفراغ","b":"بعد الوعد باليسر مع العسر، تأمر السورة بالاجتهاد في العبادة عند الفراغ، وبأن يتوجّه الرجاء إلى الرب وحده. لحظة الفراغ لها وجهة.","th":[3],"p":null,"q":[94,8]},{"id":"worship_not_sent_to_distress_you","t":"لم يُنزل ليُتعبك","b":"تفتتح سورة طه بأن القرآن لم يُنزل على النبي ليُتعبه، وإنما ليذكّر من يخاف الله. جاء ليذكّر، لا ليُرهق.","th":[3],"p":null,"q":[20,2]},{"id":"dua_good_in_both","t":"أكثر دعاء كان يدعو به","b":"حسنة في الدنيا وحسنة في الآخرة ووقاية من عذاب النار. كان النبي يدعو بهذا أكثر من غيره، وهو لا يسأل شيئًا معيّنًا.","th":[4],"p":null,"q":[2,201]},{"id":"dua_do_not_let_hearts_deviate","t":"الهداية قد تُفقد","b":"ربنا لا تُزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة. الذين دعوا بهذا كانوا مهتدين بالفعل. ولهذا بالذات دعوا به.","th":[4],"p":null,"q":[3,8]},{"id":"dua_we_have_believed","t":"الإيمان أولًا ثم الطلب","b":"ربنا إننا آمنا فاغفر لنا ذنوبنا وقنا عذاب النار. جاء الإقرار قبل السؤال، وهكذا يعلّم القرآن أن تبدأ.","th":[4],"p":null,"q":[3,16]},{"id":"dua_our_excesses","t":"سمّوا تقصيرهم هم","b":"في مواجهة عدوّ سألوا المغفرة لذنوبهم وإسرافهم في أمرهم، ثم سألوا ثبات الأقدام والنصر. بدأوا بما فيهم لا بما في العدوّ.","th":[4],"p":null,"q":[3,147]},{"id":"dua_not_created_in_vain","t":"دعاء وُلد من تفكّر","b":"الذين يذكرون الله قيامًا وقعودًا وعلى جنوبهم ويتفكّرون في خلق السماوات والأرض يقولون: ربنا ما خلقت هذا باطلًا. انتهى التفكّر إلى دعاء.","th":[4],"p":null,"q":[3,191]},{"id":"dua_die_with_the_righteous","t":"توفّنا مع الأبرار","b":"ربنا فاغفر لنا ذنوبنا وكفّر عنا سيّئاتنا وتوفّنا مع الأبرار. الطلب الأخير عن الصحبة، في اللحظة الوحيدة التي لا تستطيع ترتيبها بنفسك.","th":[4],"p":null,"q":[3,193]},{"id":"dua_pour_upon_us_patience","t":"أفرغه علينا","b":"وقد هُدّدوا بالقتل لأنهم آمنوا، سأل سحرة فرعون ربهم أن يُفرغ عليهم صبرًا وأن يتوفّاهم مسلمين. لم يسألوا النجاة. سألوا القدرة على الاحتمال.","th":[4],"p":null,"q":[7,126]},{"id":"dua_forgive_my_parents","t":"أدخلهم معك","b":"ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الحساب. سأل لثلاث جهات، وواحدة منها فقط كانت نفسه.","th":[4],"p":null,"q":[14,41]},{"id":"dua_mercy_and_right_guidance","t":"قالها فتية في كهف","b":"ربنا آتنا من لدنك رحمة وهيّئ لنا من أمرنا رشدًا. كانوا مختبئين من دولة تريد قتلهم، والذي سألوه كان رشدًا في الطريق.","th":[4],"p":null,"q":[18,10]},{"id":"dua_comfort_of_our_eyes","t":"دعاء لمن تعيش معهم","b":"ربنا هب لنا من أزواجنا وذرّيّاتنا قرّة أعين واجعلنا للمتّقين إمامًا. سُئلت سكينة البيت هنا طلبًا دينيًّا لا شأنًا خاصًّا.","th":[4],"p":null,"q":[25,74]},{"id":"dua_best_of_the_merciful","t":"آخر آية في السورة","b":"ربّ اغفر وارحم وأنت خير الراحمين. سورة كاملة عن المؤمنين المفلحين تُختم مع ذلك بطلب المغفرة.","th":[4],"p":null,"q":[23,118]},{"id":"dua_hearts_find_rest","t":"أين يُحفظ السكون","b":"ألا بذكر الله تطمئنّ القلوب. لا إلهاء ولا حلّ للمشكلة. طمأنينة، محدَّد موضعها بدقّة.","th":[4],"p":null,"q":[13,28]},{"id":"dua_remember_much","t":"العبادة الوحيدة بلا مقدار","b":"أُمر المؤمنون أن يذكروا الله ذكرًا كثيرًا. كل عبادة أخرى في القرآن تأتي بمقدارها. هذه قيل لها أن تكون كثيرة.","th":[4],"p":null,"q":[33,41]},{"id":"dua_remember_me","t":"مبادلة بشروط","b":"فاذكروني أذكركم واشكروا لي ولا تكفرون. ما تقوله بصوت خافت بعد ظهر اليوم يُجاب عنه فوق الغرفة بكثير.","th":[4],"p":null,"q":[2,152]},{"id":"dua_within_yourself","t":"بهدوء وفي الصباح","b":"واذكر ربك في نفسك تضرّعًا وخيفة ودون الجهر من القول بالغدوّ والآصال. يحدّد التوجيه الصوت والحال والوقت.","th":[4],"p":null,"q":[7,205]},{"id":"dhikr_subhanallah_hundred","t":"زبد البحر","b":"قال النبي: من قال سبحان الله وبحمده في يوم مئة مرة حُطّت خطاياه ولو كانت مثل زبد البحر. لا يميل الحساب لصالحك بهذا القدر في مكان آخر.","th":[4],"p":null,"h":{"c":"صحيح البخاري","n":"6405","u":"https://sunnah.com/bukhari:6405","g":"صحيح","by":null}},{"id":"dhikr_two_light_words","t":"خفيفتان على اللسان ثقيلتان في الميزان","b":"ذكر النبي كلمتين خفيفتين على اللسان ثقيلتين في الميزان حبيبتين إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم. لم يوصف شيء آخر بهذا.","th":[4],"p":null,"h":{"c":"صحيح البخاري","n":"6682","u":"https://sunnah.com/bukhari:6682","g":"صحيح","by":null}},{"id":"dhikr_four_most_beloved","t":"الأربع التي سمّاها","b":"قال النبي: أحبّ الكلام إلى الله أربع، لا يضرّك بأيّهنّ بدأت: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر.","th":[4],"p":null,"h":{"c":"صحيح مسلم","n":"2695","u":"https://sunnah.com/muslim:2695","g":"صحيح","by":null}},{"id":"dhikr_sayyid_al_istighfar","t":"سيّد الاستغفار","b":"علّم النبي دعاءً سمّاه سيّد الاستغفار، يُقرّ فيه العبد بالعهد ويعترف بالذنب ويسأل العفو. وقال: من قاله في النهار موقنًا به فمات من يومه دخل الجنة.","th":[4],"p":null,"h":{"c":"صحيح البخاري","n":"6306","u":"https://sunnah.com/bukhari:6306","g":"صحيح","by":null}},{"id":"dhikr_living_and_dead","t":"الحيّ والميّت","b":"شبّه النبي الذي يذكر ربه والذي لا يذكره بالحيّ والميّت. لم يوصف الفرق مسألة درجة.","th":[4],"p":null,"h":{"c":"صحيح البخاري","n":"6407","u":"https://sunnah.com/bukhari:6407","g":"صحيح","by":null}},{"id":"dhikr_gatherings_surrounded","t":"من غيرك في الغرفة","b":"قال النبي: ما اجتمع قوم في بيت من بيوت الله يتلون كتاب الله ويتدارسونه بينهم إلا نزلت عليهم السكينة وغشيتهم الرحمة وحفّتهم الملائكة وذكرهم الله فيمن عنده.","th":[4],"p":null,"h":{"c":"صحيح مسلم","n":"2699","u":"https://sunnah.com/muslim:2699","g":"صحيح","by":null}},{"id":"dhikr_when_he_remembers_me","t":"يُذكر في ملأ خير","b":"في حديث قدسي أخبر النبي أن الله يقول: أنا مع عبدي إذا ذكرني، فإن ذكرني في نفسه ذكرته في نفسي، وإن ذكرني في ملأ ذكرته في ملأ خير منهم.","th":[4],"p":null,"h":{"c":"صحيح البخاري","n":"7405","u":"https://sunnah.com/bukhari:7405","g":"صحيح","by":null}},{"id":"dua_not_hasty","t":"الطريقة الوحيدة لخسارتها","b":"قال النبي: يُستجاب لأحدكم ما لم يعجل فيقول: دعوت فلم يُستجب لي. لا شيء آخر في القائمة يُسقط حقّك.","th":[4],"p":null,"h":{"c":"صحيح مسلم","n":"2735","u":"https://sunnah.com/muslim:2735","g":"صحيح","by":null}},{"id":"dhikr_words_of_refuge","t":"كلمات لمكان غريب","b":"قال النبي: من نزل منزلًا فقال أعوذ بكلمات الله التامّات من شرّ ما خلق لم يضرّه شيء حتى يرتحل من منزله ذلك.","th":[4],"p":null,"h":{"c":"صحيح مسلم","n":"2708","u":"https://sunnah.com/muslim:2708","g":"صحيح","by":null}},{"id":"dhikr_la_ilaha_hundred","t":"مئة ودرع","b":"قال النبي: من قال لا إله إلا الله وحده لا شريك له بتمامها مئة مرة في يوم كانت له عدل عشر رقاب وكُتبت له مئة حسنة ومُحيت عنه مئة سيّئة وكانت له حرزًا من الشيطان حتى يمسي.","th":[4],"p":null,"h":{"c":"صحيح مسلم","n":"2691","u":"https://sunnah.com/muslim:2691","g":"صحيح","by":null}},{"id":"dua_abu_bakr_in_prayer","t":"ما علّمه لأبي بكر","b":"سأل أبو بكر دعاءً يدعو به في صلاته، فعُلّم أن يقول إنه ظلم نفسه ظلمًا كثيرًا، وإنه لا يغفر الذنوب إلا الله، وأن يسأل المغفرة والرحمة منه مباشرة.","th":[4],"p":null,"h":{"c":"صحيح البخاري","n":"834","u":"https://sunnah.com/bukhari:834","g":"صحيح","by":null}},{"id":"dhikr_after_the_prayer","t":"ثلاث وثلاثون في كل مرة","b":"لما خشي فقراء الصحابة أن يسبقهم أهل الأموال في الأجر، علّمهم النبي أن يسبّحوا ويحمدوا ويكبّروا ثلاثًا وثلاثين بعد كل صلاة. أُغلقت الفجوة بالكلمات.","th":[4],"p":null,"h":{"c":"صحيح البخاري","n":"843","u":"https://sunnah.com/bukhari:843","g":"صحيح","by":null}},{"id":"dhikr_treasure_of_paradise","t":"كنز تستطيع قوله","b":"قال النبي لصحابي: قل لا حول ولا قوة إلا بالله، وسمّاها كنزًا من كنوز الجنة. ثمنها نَفَس واحد.","th":[4],"p":null,"h":{"c":"صحيح مسلم","n":"2704","u":"https://sunnah.com/muslim:2704","g":"صحيح","by":null}},{"id":"dhikr_juwayriyah","t":"أربع كلمات وُزنت","b":"لما وجد النبي جويرية ما زالت جالسة في الذكر بعد ساعات من مغادرته، قال إنه قال بعدها أربع كلمات ثلاث مرات لو وُزنت بما قالته منذ الصباح لوزنتهنّ: سبحان الله وبحمده، عدد خلقه، ورضا نفسه، وزنة عرشه، ومداد كلماته.","th":[4],"p":null,"h":{"c":"صحيح مسلم","n":"2726","u":"https://sunnah.com/muslim:2726","g":"صحيح","by":null}},{"id":"dhikr_three_quls_at_night","t":"آخر شيء قبل النوم","b":"كان النبي كل ليلة يجمع كفّيه ويقرأ فيهما الإخلاص والفلق والناس ثم يمسح بهما ما استطاع من جسده، يبدأ برأسه ووجهه. كان يفعل ذلك ثلاث مرات.","th":[4],"p":null,"h":{"c":"صحيح البخاري","n":"5017","u":"https://sunnah.com/bukhari:5017","g":"صحيح","by":null}},{"id":"dua_granted_or_turned_away","t":"إجابة أو سوء يُصرف","b":"أخبر النبي أنه ما من مسلم يدعو الله بدعوة ليس فيها إثم ولا قطيعة رحم إلا أعطاه الله إياها أو صرف عنه من السوء مثلها. ولما قال الصحابة إذن نُكثر، قال إن الله أكثر.","th":[4],"p":null,"h":{"c":"جامع الترمذي","n":"3573","u":"https://sunnah.com/tirmidhi:3573","g":"حسن","by":"دار السلام"}},{"id":"dua_no_rancour_in_our_hearts","t":"قلب بلا ضغينة","b":"يصف القرآن من جاؤوا بعدُ وهم يدعون بالمغفرة لأنفسهم ولإخوانهم الذين سبقوهم في الإيمان، وبأن تخلو قلوبهم من الحقد على المؤمنين. القلب السليم مما يُسأل.","th":[4,5],"p":null,"q":[59,10]},{"id":"character_do_not_say_uff","t":"ولا حتى هذا الصوت","b":"بعد الأمر بألّا تعبد إلا إياه مباشرة يأتي الأمر بالوالدين: لا تقل لهما أفٍّ ولا تنهرهما. وُضع الحدّ عند مقطع واحد.","th":[5],"p":null,"q":[17,23]},{"id":"character_wing_of_humility","t":"اخفض الجناح","b":"واخفض لهما جناح الذلّ من الرحمة وقل ربّ ارحمهما كما ربّياني صغيرًا. كُتب دعاء لهما داخل الأمر بشأنهما.","th":[5],"p":null,"q":[17,24]},{"id":"character_carried_and_weaned","t":"فُصّلت التكلفة","b":"ووصّينا الإنسان بوالديه، ثم ذُكر ما حملته أمه: وهنًا على وهن وفصاله في عامين. أن اشكر لي ولوالديك. لم يُترك الشكر عامًّا.","th":[5],"p":null,"q":[31,14]},{"id":"character_thirty_and_forty","t":"دعاء ابن كبِر","b":"عند الأربعين يقول: ربّ أوزعني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ وأن أعمل صالحًا ترضاه وأصلح لي في ذرّيّتي. ثلاثة أجيال في دعاء واحد.","th":[5],"p":null,"q":[46,15]},{"id":"character_worship_and_parents","t":"ثم الشارع كله","b":"اعبدوا الله ولا تشركوا به شيئًا وبالوالدين إحسانًا وبذي القربى واليتامى والمساكين والجار ذي القربى والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت أيمانكم. القائمة تتّسع باستمرار.","th":[5],"p":null,"q":[4,36]},{"id":"character_most_noble","t":"الترتيب الوحيد الذي يعترف به","b":"وجعلناكم شعوبًا وقبائل لتعارفوا. إن أكرمكم عند الله أتقاكم. وكل جدول ترتيب آخر من اختراعك أنت.","th":[5],"p":null,"q":[49,13]},{"id":"character_avoid_suspicion","t":"ثلاثة في آية واحدة","b":"اجتنبوا كثيرًا من الظنّ إن بعض الظنّ إثم، ولا تجسّسوا، ولا يغتب بعضكم بعضًا. ثم تسأل الآية: أيحبّ أحدكم أن يأكل لحم أخيه ميتًا؟","th":[5],"p":null,"q":[49,12]},{"id":"character_believers_are_brothers","t":"فاذهب وأصلح","b":"إنما المؤمنون إخوة فأصلحوا بين أخويكم. يأتي بيان القرابة ومعه واجب في الجملة نفسها.","th":[5],"p":null,"q":[49,10]},{"id":"character_affection_and_mercy","t":"جُعل بينكما","b":"ومن آياته أن خلق لكم من أنفسكم أزواجًا لتسكنوا إليها وجعل بينكم مودّة ورحمة. وُصف الشعور بأنه شيء جعله هو هناك، لا شيء صنعته أنت.","th":[5],"p":null,"q":[30,21]},{"id":"character_best_nation","t":"لأجل ماذا كان اللقب","b":"كنتم خير أمّة أُخرجت للناس: تأمرون بالمعروف وتنهون عن المنكر وتؤمنون بالله. يتبع الوصفَ مباشرةً العملُ الذي يستحقّه.","th":[5],"p":null,"q":[3,110]},{"id":"character_restrain_anger","t":"اكظم ثم اعفُ","b":"الذين ينفقون في السرّاء والضرّاء والكاظمين الغيظ والعافين عن الناس. والله يحبّ المحسنين. اثنتان من الصفات الثلاث عمّا لا تفعله.","th":[5],"p":null,"q":[3,134]},{"id":"character_repel_with_better","t":"ردّ بأحسن","b":"ادفع بالتي هي أحسن فإذا الذي بينك وبينه عداوة كأنه وليّ حميم. تعد الآية بنتيجة لا يجرّبها أكثر الناس أبدًا.","th":[5],"p":null,"q":[41,34]},{"id":"character_walk_gently","t":"كيف يمشون","b":"وعباد الرحمن الذين يمشون على الأرض هونًا وإذا خاطبهم الجاهلون قالوا سلامًا. يبدأ الوصف بخطواتهم وينتهي بأجوبتهم.","th":[5],"p":null,"q":[25,63]},{"id":"character_the_steep_path","t":"الطريق الصاعد","b":"وما العقبة؟ فكّ رقبة أو إطعام في يوم ذي مسغبة يتيمًا ذا مقربة أو مسكينًا ذا متربة. يعرّف القرآن الطريق الصعب بأنه أن تُطعم إنسانًا.","th":[5],"p":null,"q":[90,14]},{"id":"character_in_spite_of_love","t":"وهم ما زالوا يشتهونه","b":"ويطعمون الطعام على حبّه مسكينًا ويتيمًا وأسيرًا. لا تقول الآية إن عندهم فائضًا. تقول إنهم أعطوا ما يريدونه.","th":[5],"p":null,"q":[76,8]},{"id":"character_one_body","t":"جسد واحد وحمّى واحدة","b":"قال النبي: مثل المؤمنين في توادّهم وتراحمهم وتعاطفهم مثل الجسد، إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمّى. ليس تعاطفًا. حمّى.","th":[5],"p":null,"h":{"c":"صحيح البخاري","n":"6011","u":"https://sunnah.com/bukhari:6011","g":"صحيح","by":null}},{"id":"character_love_for_your_brother","t":"الحديث الثالث عشر","b":"قال النبي: لا يؤمن أحدكم حتى يحبّ لأخيه ما يحبّ لنفسه. وهو قريب جدًّا من أول صحيح البخاري، وهذا يدلّك على المكانة التي أُعطيها.","th":[5],"p":null,"h":{"c":"صحيح البخاري","n":"13","u":"https://sunnah.com/bukhari:13","g":"صحيح","by":null}},{"id":"character_best_to_his_family","t":"يُقاس في البيت","b":"قال النبي: خيركم خيركم لأهله، وأنا خيركم لأهلي. وُضع اختبار الخُلق داخل البيت.","th":[5],"p":null,"h":{"c":"جامع الترمذي","n":"3895","u":"https://sunnah.com/tirmidhi:3895","g":"صحيح","by":"دار السلام"}},{"id":"character_your_mother_three_times","t":"سُئل أربع مرات","b":"سأل رجل: من أحقّ الناس بحسن صحبتي؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: ثم أبوك. التكرار هو الجواب.","th":[5],"p":null,"h":{"c":"صحيح البخاري","n":"5971","u":"https://sunnah.com/bukhari:5971","g":"صحيح","by":null}},{"id":"character_ties_of_kinship","t":"رزق عبر الناس","b":"قال النبي: من أحبّ أن يُبسط له في رزقه وينسأ له في أثره فليصل رحمه. القريب الذي لم تتّصل به مذكور تحت باب الرزق.","th":[5],"p":null,"h":{"c":"صحيح البخاري","n":"5985","u":"https://sunnah.com/bukhari:5985","g":"صحيح","by":null}},{"id":"character_speak_good_or_be_silent","t":"ثلاث جمل وإيمان واحد","b":"من كان يؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمت، ومن كان يؤمن بالله واليوم الآخر فليكرم جاره، ومن كان يؤمن بالله واليوم الآخر فليكرم ضيفه. كل واجب رُبط بالإقرار نفسه.","th":[5],"p":null,"h":{"c":"صحيح البخاري","n":"6018","u":"https://sunnah.com/bukhari:6018","g":"صحيح","by":null}},{"id":"character_he_looks_at_hearts","t":"لا إلى صوركم","b":"قال النبي: إن الله لا ينظر إلى أجسادكم ولا إلى صوركم ولكن ينظر إلى قلوبكم وأعمالكم، ثم قال: كل المسلم على المسلم حرام، دمه وماله وعرضه.","th":[5],"p":null,"h":{"c":"صحيح مسلم","n":"2564","u":"https://sunnah.com/muslim:2564","g":"صحيح","by":null}},{"id":"character_heaviest_on_the_scale","t":"أثقل من كل شيء","b":"أخبر النبي أنه ليس شيء أثقل في ميزان المؤمن يوم القيامة من حسن الخلق، وأن الله يبغض الفاحش البذيء.","th":[5],"p":null,"h":{"c":"جامع الترمذي","n":"2002","u":"https://sunnah.com/tirmidhi:2002","g":"صحيح","by":"دار السلام"}},{"id":"character_charity_does_not_decrease","t":"ثلاثة تسير عكس البديهة","b":"ما نقصت صدقة من مال. وما زاد الله عبدًا بعفو إلا عزًّا. وما تواضع أحد لله إلا رفعه الله. كل وعد منها يجري عكس ما تظنّ.","th":[5],"p":null,"h":{"c":"صحيح مسلم","n":"2588","u":"https://sunnah.com/muslim:2588","g":"صحيح","by":null}},{"id":"character_relieve_a_hardship","t":"من ستر سُتر","b":"قال النبي: من نفّس عن مسلم كربة من كرب الدنيا نفّس الله عنه كربة من كرب يوم القيامة، ومن ستر مسلمًا ستره الله.","th":[5],"p":null,"h":{"c":"صحيح البخاري","n":"2442","u":"https://sunnah.com/bukhari:2442","g":"صحيح","by":null}},{"id":"character_shown_mercy_by_the_merciful","t":"الرحمة تعود رحمة","b":"أخبر النبي أن الراحمين يرحمهم الرحمن، وأوصى بأن نرحم من في الأرض ليرحمنا من في السماء. الرحمة التي ترجوها هي الرحمة التي يُطلب منك أن تعطيها.","th":[5,1],"p":null,"h":{"c":"جامع الترمذي","n":"1924","u":"https://sunnah.com/tirmidhi:1924","g":"حسن","by":"دار السلام"}},{"id":"character_your_smile_is_charity","t":"صدقة بلا مال","b":"عدّ النبي تبسّمك في وجه أخيك صدقة، وكذلك إرشاد الضالّ، وإعانة ضعيف البصر، وإماطة الحجر والشوكة عن الطريق، وأن تُفرغ من دلوك في دلو أخيك. أكثرها لا يكلّف إلا الانتباه.","th":[5],"p":null,"h":{"c":"جامع الترمذي","n":"1956","u":"https://sunnah.com/tirmidhi:1956","g":"حسن","by":"دار السلام"}},{"id":"character_best_to_the_one_beside_you","t":"خيرهم لمن بجانبه","b":"أخبر النبي أن خير الأصحاب عند الله خيرهم لصاحبه، وخير الجيران عند الله خيرهم لجاره. أقرب الناس إليك هم موضع هذا الميزان.","th":[5],"p":null,"h":{"c":"جامع الترمذي","n":"1944","u":"https://sunnah.com/tirmidhi:1944","g":"صحيح","by":"دار السلام"}},{"id":"character_the_first_words_he_heard","t":"أول ما سمعه منه","b":"لما قدم النبي المدينة نظر عبد الله بن سلام إلى وجهه فعرف أنه ليس بوجه كذاب. وكان أول ما سمعه منه أمرٌ بإفشاء السلام، وإطعام الطعام، والصلاة والناس نيام، ووعدٌ بدخول الجنة بسلام.","th":[5,3],"p":null,"h":{"c":"جامع الترمذي","n":"2485","u":"https://sunnah.com/tirmidhi:2485","g":"صحيح","by":"دار السلام"}},{"id":"character_the_young_and_the_old","t":"الصغير والكبير","b":"أخبر النبي أن من لم يرحم صغيرنا ولم يعرف شرف كبيرنا فليس منا. الانتماء هنا رقّة في اتجاه، وتوقير في الاتجاه الآخر.","th":[5,1],"p":null,"h":{"c":"جامع الترمذي","n":"1920","u":"https://sunnah.com/tirmidhi:1920","g":"حسن","by":"دار السلام"}},{"id":"character_a_date_that_grows","t":"تمرة تصير جبلًا","b":"أخبر النبي أن من تصدّق بما يعدل تمرة من كسب طيب قبلها الله ونمّاها لصاحبها كما يربّي أحدكم مُهره، حتى تصير مثل الجبل.","th":[5,7],"p":null,"h":{"c":"صحيح البخاري","n":"1410","u":"https://sunnah.com/bukhari:1410","g":"صحيح","by":null}},{"id":"character_the_better_of_the_two","t":"خيرهما","b":"أخبر النبي أنه لا يحلّ للمرء أن يهجر أخاه فوق ثلاث ليال، يلتقيان فيُعرض هذا ويُعرض هذا، وأن خيرهما الذي يبدأ بالسلام. كثيرًا ما يكون السلام طريق العودة.","th":[5],"p":null,"h":{"c":"صحيح البخاري","n":"6077","u":"https://sunnah.com/bukhari:6077","g":"صحيح","by":null}},{"id":"character_deprived_of_gentleness","t":"من حُرم الرفق","b":"أخبر النبي أن من يُحرم الرفق يُحرم الخير. جملة قصيرة يمتدّ أثرها إلى طريقة كلامنا، وتصويبنا للآخرين، وانتظارنا، وجوابنا.","th":[5],"p":null,"h":{"c":"صحيح مسلم","n":"2592a","u":"https://sunnah.com/muslim:2592a","g":"صحيح","by":null}},{"id":"character_given_where_no_one_sees","t":"عطاء لا يراه أحد","b":"تقول الآية إن إظهار الصدقة حسن، وإن إعطاءها المحتاجين في خفاء خير لك، وبها يمحو الله بعض السيئات. والله مطّلع على ما تعمل حتى حين لا يراك أحد.","th":[5],"p":null,"q":[2,271]},{"id":"character_a_kind_word_comes_first","t":"الكلمة الطيبة أولًا","b":"تقول الآية إن الكلام الطيب والصفح خير من صدقة يعقبها إيذاء، والله غنيّ حليم. أحيانًا تكون الهدية في طريقة العطاء، وفيما يُترك دون أن يُقال.","th":[5],"p":null,"q":[2,263]},{"id":"character_say_what_is_best","t":"أحسن الكلام","b":"يأمر الله عباده أن يقولوا أحسن الكلام، لأن الشيطان يفسد بين الناس. ليس ما هو صحيح فحسب، ولا ما هو جائز فحسب، بل ما هو أحسن.","th":[5],"p":null,"q":[17,53]},{"id":"character_return_it_with_better","t":"تحية بأفضل منها","b":"تأمر الآية من أُلقيت عليه التحية أن يجيب بخير منها، أو بمثلها على الأقل، والله يحصي كل شيء. حتى السلام محسوب.","th":[5],"p":null,"q":[4,86]},{"id":"hereafter_every_soul_tastes","t":"ثم تُوفّى أجرك كاملًا","b":"كل نفس ذائقة الموت، وإنما توفّون أجوركم يوم القيامة. لا شيء يُسوّى هنا. ليس هنا حيث تُقفل الحسابات.","th":[6],"p":null,"q":[3,185]},{"id":"hereafter_created_death_and_life","t":"والموت أيضًا خُلق","b":"خلق الموت والحياة ليبلوكم أيكم أحسن عملًا. ذُكر الموت أولًا ووُصف بأنه مخلوق عن قصد لا حادث في النهاية.","th":[6],"p":null,"q":[67,2]},{"id":"hereafter_then_returned","t":"اتجاه الرحلة","b":"كل نفس ذائقة الموت ثم إلينا تُرجعون. تذكر الآية الوجهة في النَّفَس ذاته الذي تذكر فيه المغادرة.","th":[6],"p":null,"q":[29,57]},{"id":"hereafter_it_will_meet_you","t":"هو آتٍ ليجدك","b":"قل إن الموت الذي تفرّون منه فإنه ملاقيكم ثم تُردّون إلى عالم الغيب والشهادة. عُولج الهروب مباشرة ورُدّ.","th":[6],"p":null,"q":[62,8]},{"id":"hereafter_if_only_you_would_delay","t":"الطلب الذي يأتي متأخّرًا","b":"وأنفقوا مما رزقناكم من قبل أن يأتي أحدكم الموت فيقول: ربّ لولا أخّرتني إلى أجل قريب فأصّدّق. يسجّل القرآن الطلب واللحظة التي يصير فيها مستحيلًا.","th":[6],"p":null,"q":[63,10]},{"id":"hereafter_atom_of_good","t":"حتى مثقال ذرّة","b":"فمن يعمل مثقال ذرّة خيرًا يره، ومن يعمل مثقال ذرّة شرًّا يره. لم يكن شيء قط أصغر من أن يُسجّل، في الاتجاهين.","th":[6],"p":null,"q":[99,7]},{"id":"hereafter_the_scales","t":"تُوزن لا تُعدّ","b":"فأما من ثقلت موازينه فهو في عيشة راضية. المقياس بالوزن، والوزن ليس هو الكمّ.","th":[6],"p":null,"q":[101,6]},{"id":"hereafter_no_soul_possesses","t":"لا أحد ينوب عنك","b":"يوم لا تملك نفس لنفس شيئًا والأمر يومئذ لله. كل ترتيب تعتمد عليه الآن موصوف بأنه غائب هناك.","th":[6],"p":null,"q":[82,19]},{"id":"hereafter_sound_heart","t":"الشيء الوحيد الذي تحمله","b":"يوم لا ينفع مال ولا بنون إلا من أتى الله بقلب سليم. شيء واحد يعبر، وهو ليس مذكورًا في أي جرد.","th":[6],"p":null,"q":[26,89]},{"id":"hereafter_reassured_soul","t":"نودِيت باسمها","b":"يا أيتها النفس المطمئنّة ارجعي إلى ربك راضية مرضية، فادخلي في عبادي وادخلي جنّتي. أربع جمل وكل واحدة منها دعوة.","th":[6],"p":null,"q":[89,27]},{"id":"hereafter_closer_than_jugular","t":"أقرب من نبضك","b":"ولقد خلقنا الإنسان ونعلم ما توسوس به نفسه ونحن أقرب إليه من حبل الوريد. الوسوسة داخلة في ذلك. لا شيء يفوت.","th":[6],"p":null,"q":[50,16]},{"id":"hereafter_amusement_and_diversion","t":"اقرأ الوصف","b":"اعلموا أنما الحياة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الأموال والأولاد. ثم تشبّهها الآية بغيث أعجب الزرّاع قبل أن يهيج.","th":[6],"p":null,"q":[57,20]},{"id":"hereafter_you_prefer_this_life","t":"بل تؤثرون","b":"بل تؤثرون الحياة الدنيا، والآخرة خير وأبقى. لا تتّهم الآية أحدًا بالكفر. تتّهم بتفضيل.","th":[6],"p":null,"q":[87,16]},{"id":"hereafter_enduring_good_deeds","t":"زينة ثم ما يبقى","b":"المال والبنون زينة الحياة الدنيا، والباقيات الصالحات خير عند ربك ثوابًا وخير أملًا. نصفا الآية صادقان في وقت واحد.","th":[6],"p":null,"q":[18,46]},{"id":"hereafter_everyone_will_perish","t":"كل من عليها","b":"كل من عليها فان، ويبقى وجه ربك ذو الجلال والإكرام. تُفرغ الآية الغرفة ثم تسمّي من بقي.","th":[6],"p":null,"q":[55,26]},{"id":"hereafter_home_of_settlement","t":"مجرد عبور","b":"إنما هذه الحياة الدنيا متاع وإن الآخرة هي دار القرار. إحدى هاتين الكلمتين تصف المكان الذي تفرغ فيه حقائبك.","th":[6],"p":null,"q":[40,39]},{"id":"hereafter_three_follow","t":"اثنان يرجعان","b":"قال النبي: يتبع الميت ثلاثة: أهله وماله وعمله. فيرجع اثنان ويبقى واحد.","th":[6],"p":null,"h":{"c":"صحيح البخاري","n":"6514","u":"https://sunnah.com/bukhari:6514","g":"صحيح","by":null}},{"id":"hereafter_stranger_or_traveller","t":"غريب أو عابر سبيل","b":"أخذ النبي بمنكبَي صاحب له وقال له: كن في الدنيا كأنك غريب أو عابر سبيل. وكان ابن عمر يزيد: إذا أمسيت فلا تنتظر الصباح.","th":[6],"p":null,"h":{"c":"صحيح البخاري","n":"6416","u":"https://sunnah.com/bukhari:6416","g":"صحيح","by":null}},{"id":"hereafter_three_that_continue","t":"ثلاثة تواصل العمل","b":"قال النبي: إذا مات الإنسان انقطع عمله إلا من ثلاث: صدقة جارية، أو علم يُنتفع به، أو ولد صالح يدعو له. بعض العمل يعيش بعد صاحبه.","th":[6],"p":null,"h":{"c":"صحيح مسلم","n":"1631","u":"https://sunnah.com/muslim:1631","g":"صحيح","by":null}},{"id":"hereafter_surrounded_by_hardship","t":"بماذا أُحيط كل منهما","b":"قال النبي: حُفّت الجنة بالمكاره وحُفّت النار بالشهوات. لا يُبلغ أيّهما مصادفة، والطريق الأسهل هو الخطأ.","th":[6],"p":null,"h":{"c":"صحيح مسلم","n":"2822","u":"https://sunnah.com/muslim:2822","g":"صحيح","by":null}},{"id":"gratitude_if_you_are_grateful","t":"الزيادة موعودة","b":"لئن شكرتم لأزيدنّكم. تذكر الآية النتيجة يقينًا ولا تقول ممّ ستكون الزيادة.","th":[7],"p":null,"q":[14,7]},{"id":"gratitude_cannot_enumerate","t":"لن تنتهي من العدّ","b":"وإن تعدّوا نعمة الله لا تحصوها. ابدأ بأنك تقرأ وتتنفّس وتفهم هذه الجملة.","th":[7],"p":null,"q":[16,18]},{"id":"gratitude_for_himself","t":"كان دائمًا لك أنت","b":"ومن يشكر فإنما يشكر لنفسه، ومن كفر فإن الله غنيّ حميد. لم يكن الشكر يومًا شيئًا يحتاجه منك.","th":[7],"p":null,"q":[31,12]},{"id":"gratitude_which_favours","t":"سُئل إحدى وثلاثين مرة","b":"فبأيّ آلاء ربكما تكذّبان؟ يتكرّر السؤال في السورة كلها، بعد الرحمة وبعد الخلق وبعد الرزق، حتى يصير رفض الجواب هو الجواب.","th":[7],"p":null,"q":[55,13]},{"id":"gratitude_provision_guaranteed","t":"كل مخلوق في القائمة","b":"وما من دابّة في الأرض إلا على الله رزقها ويعلم مستقرّها ومستودعها. لم تُضيَّق الكفالة على البشر.","th":[7],"p":null,"q":[11,6]},{"id":"gratitude_creatures_carry_nothing","t":"لا تحمل مؤونة","b":"وكأيّن من دابّة لا تحمل رزقها، الله يرزقها وإياكم. تقارن الآية قلقك بطائر لم يخطّط لغد مرة واحدة.","th":[7],"p":null,"q":[29,60]},{"id":"gratitude_he_compensates_it","t":"يعود إليك","b":"وما أنفقتم من شيء فهو يخلفه، وهو خير الرازقين. تصف الآية الإنفاق تحويلًا لا خسارة.","th":[7],"p":null,"q":[34,39]},{"id":"gratitude_report_the_favour","t":"قلها بصوت مسموع","b":"وأما بنعمة ربك فحدّث. بعد التوجيه في شأن اليتيم والسائل مباشرة يأتي الأمر بالحديث عمّا أُعطيته.","th":[7],"p":null,"q":[93,11]},{"id":"gratitude_al_kawthar","t":"أُعطيت الكثير","b":"إنا أعطيناك الكوثر. ثلاث آيات، نزلت على رجل سُخر منه للتوّ بأنه أبتر، وتفتتح بأن تخبره بما يملكه فعلًا.","th":[7],"p":null,"q":[108,1]},{"id":"gratitude_look_at_the_camels","t":"انظر إلى الإبل","b":"أفلا ينظرون إلى الإبل كيف خُلقت، وإلى السماء كيف رُفعت، وإلى الجبال، وإلى الأرض؟ الدعوة أن تلاحظ الأشياء العادية كما ينبغي.","th":[7],"p":null,"q":[88,17]},{"id":"gratitude_bitter_water","t":"كان يمكن أن يكون أُجاجًا","b":"أفرأيتم الماء الذي تشربون؟ لو نشاء جعلناه أُجاجًا فلولا تشكرون. الحجّة كلها تُقام بكوب ماء.","th":[7],"p":null,"q":[56,70]},{"id":"gratitude_pleased_by_praise","t":"جملة واحدة تُرضيه","b":"قال النبي: إن الله ليرضى عن العبد أن يأكل الأكلة فيحمده عليها أو يشرب الشربة فيحمده عليها. رضا ربك معلّق بجملة تُقال بعد الطعام.","th":[7],"p":null,"h":{"c":"صحيح مسلم","n":"2734a","u":"https://sunnah.com/muslim:2734a","g":"صحيح","by":null}},{"id":"gratitude_richness_of_the_soul","t":"أين يُخزَّن الغنى","b":"قال النبي: ليس الغنى عن كثرة العرض، ولكن الغنى غنى النفس. نُقل التعريف من الحساب إلى الإنسان.","th":[7],"p":null,"h":{"c":"صحيح البخاري","n":"6446","u":"https://sunnah.com/bukhari:6446","g":"صحيح","by":null}},{"id":"gratitude_whoever_wakes_secure","t":"ثلاثة والدنيا كلها","b":"قال النبي: من أصبح منكم آمنًا في سربه معافى في جسده عنده قوت يومه فكأنما حيزت له الدنيا. قابل هذه القائمة بصباحك.","th":[7],"p":null,"h":{"c":"جامع الترمذي","n":"2346","u":"https://sunnah.com/tirmidhi:2346","g":"حسن","by":"دار السلام"}},{"id":"gratitude_two_blessings","t":"أكثر اثنتين تُضيّعان","b":"قال النبي: نعمتان مغبون فيهما كثير من الناس: الصحة والفراغ. كلتاهما تُنفَق الآن، قرّرت كيف أو لم تقرّر.","th":[7],"p":null,"h":{"c":"صحيح البخاري","n":"6412","u":"https://sunnah.com/bukhari:6412","g":"صحيح","by":null}},{"id":"gratitude_thanks_that_begins_with_people","t":"شكر يبدأ بالناس","b":"أخبر النبي أن من لا يشكر الناس لا يشكر الله. شكره لا ينفصل عن شكر من تصل إليك نعمه على أيديهم.","th":[7,5],"p":null,"h":{"c":"جامع الترمذي","n":"1954","u":"https://sunnah.com/tirmidhi:1954","g":"صحيح","by":"دار السلام"}},{"id":"gratitude_the_best_remembrance","t":"أفضل الذكر وأفضل الدعاء","b":"أخبر النبي أن أفضل الذكر لا إله إلا الله، وأفضل الدعاء الحمد لله. كلمتان قصيرتان حاضرتان في أي لحظة من اليوم.","th":[7,4],"p":null,"h":{"c":"جامع الترمذي","n":"3383","u":"https://sunnah.com/tirmidhi:3383","g":"حسن","by":"دار السلام"}},{"id":"gratitude_where_to_rest_your_eyes","t":"أين تضع نظرك","b":"أوصى النبي أن ننظر إلى من هو أسفل منا لا إلى من هو فوقنا، فذلك أجدر ألا نستصغر نعمة الله علينا. المقارنة قد تغذّي الشكر وقد تُجوّعه.","th":[7],"p":null,"h":{"c":"صحيح مسلم","n":"2963c","u":"https://sunnah.com/muslim:2963c","g":"صحيح","by":null}}]};
